import assert from 'node:assert/strict';
import fs from 'node:fs';
import path from 'node:path';
import ts from './typescript-runtime.mjs';

const root=path.resolve(import.meta.dirname,'..'),modules=new Map();
const compile=filename=>{
  if(modules.has(filename))return modules.get(filename);
  const compiled=ts.transpileModule(fs.readFileSync(filename,'utf8'),{compilerOptions:{target:ts.ScriptTarget.ES2022,module:ts.ModuleKind.ES2022},fileName:filename,reportDiagnostics:true});
  assert.equal(compiled.diagnostics?.length??0,0,'TV helper TypeScript syntax');
  const source=compiled.outputText.replace(/from\s+(['"])(\.\/[^'"]+)\1/g,(_match,_quote,specifier)=>`from '${compile(path.resolve(path.dirname(filename),specifier+'.ts'))}'`);
  const url=`data:text/javascript;base64,${Buffer.from(source).toString('base64')}`;modules.set(filename,url);return url;
};
const m=await import(compile(path.join(root,'src/lib/tvDashboard.ts'))),now=1_800_000_000_000;
const status=extra=>({state:'printing',connectionState:'online',filename:'part.gcode',progress:.4,printDuration:1200,nozzle:210,nozzleTarget:210,bed:60,bedTarget:60,telemetryUpdatedAt:now,jobUpdatedAt:now,...extra});
const printer=(id,extra={})=>({id,name:'Printer '+id,host:'printer.local',webcams:[],status:status(extra)});
const current=printer('printing');
assert.equal(m.tvPrinterState(current,now),'printing');
assert.equal(m.tvPrinterState(printer('ready',{state:'ready'}),now),'ready');
assert.equal(m.tvPrinterState(printer('paused',{state:'paused'}),now),'paused');
assert.equal(m.tvPrinterState(printer('offline',{connectionState:'offline'}),now),'offline','retained print state must not hide lost connection');
assert.equal(m.tvPrinterState(printer('error',{state:'ready',klippyState:'shutdown'}),now),'error','firmware shutdown must not become a free printer');
assert.equal(m.tvPrinterState(printer('auth',{state:'ready',connectionReason:'authorization'}),now),'error');
assert.equal(m.tvPrinterState(printer('autonomous',{remoteControlSuspended:true}),now),'unknown');
assert.equal(m.tvPrinterState(printer('connecting',{state:'ready',connectionState:'connecting'}),now),'unknown');
assert.equal(m.tvPrinterState(printer('never-seen',{state:'ready',jobUpdatedAt:undefined}),now),'unknown','an unconfirmed saved printer is never ready');
assert.equal(m.tvPrinterState(printer('expired',{state:'ready',jobUpdatedAt:now-120_001}),now),'unknown','expired data cannot free a printer');
assert.equal(m.tvPrinterState(printer('stale',{jobUpdatedAt:now-45_000,telemetryUpdatedAt:now-45_000}),now),'printing','recent stale state can remain visible with its age');
assert.equal(m.tvFreshness(printer('stale',{jobUpdatedAt:now-45_000,telemetryUpdatedAt:now-45_000}),now).tone,'stale');
assert.match(m.tvFreshness(printer('expired',{jobUpdatedAt:now-180_000,telemetryUpdatedAt:now-180_000}),now).label,/Нет свежих данных.*3 мин/);
assert.match(m.tvFreshness(printer('offline',{connectionState:'offline',lastSeen:now-180_000}),now).label,/Последний ответ 3 мин/);
assert.equal(m.tvProgress(current,now),40);
assert.equal(m.tvProgress(printer('nan',{progress:NaN}),now),undefined);
assert.equal(m.tvProgress(printer('overflow',{progress:1.5}),now),100);
assert.equal(m.tvProgress(printer('negative',{progress:-1}),now),0);
assert.equal(m.tvProgress(printer('expired',{jobUpdatedAt:now-120_001}),now),undefined,'an old job cannot display a current percentage');
assert.equal(m.tvRemainingSeconds(current,now),1800,'remaining time derives from actual elapsed time and progress');
for(const extra of[{state:'paused'},{connectionState:'offline'},{progress:0},{progress:.01},{progress:1},{progress:NaN},{printDuration:59},{jobUpdatedAt:now-20_001}])assert.equal(m.tvRemainingSeconds(printer('no-estimate',extra),now),undefined,'no invented ETA for '+JSON.stringify(extra));
assert.equal(m.tvDuration(1),'1 мин');assert.equal(m.tvDuration(3600),'1 ч');assert.equal(m.tvDuration(3660),'1 ч 1 мин');
const fleet=[current,printer('ready',{state:'ready'}),printer('paused',{state:'paused'}),printer('error',{state:'error',message:'Ошибка нагрева'}),printer('offline',{connectionState:'offline'}),printer('stale',{jobUpdatedAt:now-45_000,telemetryUpdatedAt:now-45_000}),printer('unknown',{jobUpdatedAt:undefined,telemetryUpdatedAt:undefined})];
assert.deepEqual(m.tvSummary(fleet,now),{printing:2,ready:1,paused:1,error:1,offline:1,unknown:1});
const maintenance={version:1,tasks:[{id:'due',printerId:'printing',title:'Очистить сопло',intervalHours:50,lastAt:now-100,baselineSeconds:0,cycleId:'cycle-1'},{id:'later',printerId:'ready',title:'Смазать оси',intervalHours:100,lastAt:now-100,baselineSeconds:0,cycleId:'cycle-1'}],meters:{printing:{totalSeconds:50*3600},ready:{totalSeconds:5*3600}},configuredPrinterIds:['printing','ready']};
assert.deepEqual(m.tvDueTasks('printing',maintenance).map(task=>task.id),['due']);
assert.deepEqual(m.tvDueTasks('ready',maintenance),[]);
const notices=m.tvNotices(fleet,now,maintenance);
