assert.match(notices[0].detail,/Ошибка нагрева/);
assert.ok(notices.some(notice=>notice.id==='maintenance:printing'&&notice.detail==='Очистить сопло'));
assert.ok(notices.some(notice=>notice.id==='freshness:stale'&&/устарели/.test(notice.detail)));
assert.ok(m.tvNotices([printer('degraded',{connectionState:'degraded',connectionMessage:'Связь нестабильна'})],now).some(notice=>notice.id==='freshness:degraded'&&notice.detail==='Связь нестабильна'),'degraded connection must remain visible even when a latest snapshot looks fresh');
assert.ok(!notices.some(notice=>notice.printerId==='ready'),'ready printer requires no spurious warning');
assert.deepEqual(m.tvNotices([],now),[]);
assert.deepEqual(m.tvLayout(1920,1080),{columns:4,pageSize:8});
assert.deepEqual(m.tvLayout(910,512),{columns:2,pageSize:2});
assert.deepEqual(m.tvLayout(390,844),{columns:1,pageSize:2});
for(const [width,height]of[[390,512],[600,512],[1099,900],[1366,768],[1920,512],[3840,2160]]){
  const layout=m.tvLayout(width,height);assert.ok(layout.columns>=1&&layout.pageSize>=layout.columns);
  const ids=Array.from({length:20},(_,index)=>'printer-'+index),pages=Array.from({length:Math.ceil(ids.length/layout.pageSize)},(_,index)=>ids.slice(index*layout.pageSize,(index+1)*layout.pageSize));
  assert.deepEqual(pages.flat(),ids,'pagination preserves all printers exactly once at '+width+'×'+height);
}
