import fs from 'node:fs';
import path from 'node:path';
import crypto from 'node:crypto';
import { Readable, Transform } from 'node:stream';
import { pipeline } from 'node:stream/promises';
import { fileURLToPath } from 'node:url';

// A reviewed, immutable model contract. No model or inference code is fetched at app runtime.
export const CAMERA_MODEL=Object.freeze({
  id:'obico-failure-5a6b1be1fa',
  file:'obico-failure-5a6b1be1fa.onnx',
  url:'https://www.obico.io/static_pub/ml-models/model-weights-5a6b1be1fa.onnx',
  size:202223918,
  sha256:'0a6ebd8e30dbf6a450c50f9c0a5406f04ba7eb1c99fd5996e888c78bb383b9aa',
  source:'https://github.com/TheSpaghettiDetective/obico-server/tree/6f938964c63892df2b6d5b68d99ea783fc1a7c78/ml_api',
  sourceCommit:'6f938964c63892df2b6d5b68d99ea783fc1a7c78',
  input:{name:'input',type:'float32',shape:[1,3,416,416],preprocessing:'RGB; bilinear resize; NCHW; divide by 255'},
  outputs:{boxes:[1,845,1,4],confs:[1,845,1]},
  labels:['failure'],
  runtime:'onnxruntime-web@1.23.2',
});
const root=fileURLToPath(new URL('..',import.meta.url));
const destination=path.join(root,'public','camera-detector');
const modelPath=path.join(destination,CAMERA_MODEL.file);
const hashFile=async filename=>{
  const hash=crypto.createHash('sha256');
  for await(const chunk of fs.createReadStream(filename))hash.update(chunk);
  return hash.digest('hex');
};

async function verifyModel(filename){
  const stat=await fs.promises.stat(filename);
  if(stat.size!==CAMERA_MODEL.size)throw new Error(`Camera model size mismatch: ${stat.size}`);
  if(await hashFile(filename)!==CAMERA_MODEL.sha256)throw new Error('Camera model SHA256 mismatch');
}

async function downloadModel(){
  const temporary=`${modelPath}.download-${process.pid}`;
  try{
    const response=await fetch(CAMERA_MODEL.url,{signal:AbortSignal.timeout(180_000)});
    if(!response.ok||!response.body)throw new Error(`Camera model download failed: HTTP ${response.status}`);
    let size=0;
    const limit=new Transform({transform(chunk,encoding,callback){
      size+=chunk.length;
      callback(size>CAMERA_MODEL.size?new Error('Camera model download exceeds pinned size'):null,chunk);
    }});
    await pipeline(Readable.fromWeb(response.body),limit,fs.createWriteStream(temporary,{flags:'wx'}));
    await verifyModel(temporary);
    await fs.promises.rename(temporary,modelPath);
  }finally{await fs.promises.rm(temporary,{force:true})}
}

export async function prepareCameraDetector({download=false}={}){
  await fs.promises.mkdir(destination,{recursive:true});
  if(!fs.existsSync(modelPath)){
    if(!download)throw new Error('Pinned camera model missing. Run node scripts/prepare-camera-detector.mjs --download once before building.');
    await downloadModel();
  }
  await verifyModel(modelPath);
  const packageRoot=path.join(root,'node_modules','onnxruntime-web');
  const runtime=JSON.parse(await fs.promises.readFile(path.join(packageRoot,'package.json'),'utf8'));
  if(runtime.version!=='1.23.2')throw new Error('Unexpected ONNX Runtime Web version');
  const licenses=['OBICO-LICENSE.txt','ONNXRUNTIME-LICENSE.txt','ONNXRUNTIME-ThirdPartyNotices.txt','NOTICE.txt'];
  for(const filename of licenses){
    const text=await fs.promises.readFile(path.join(destination,filename),'utf8');
    if(text.length<(filename==='NOTICE.txt'?300:1000))throw new Error(`Missing detector license: ${filename}`);
  }
  const assets=['ort-wasm-simd-threaded.mjs','ort-wasm-simd-threaded.wasm'];
  for(const filename of assets)await fs.promises.copyFile(path.join(packageRoot,'dist',filename),path.join(destination,filename));
  const manifest={...CAMERA_MODEL,licenses,assets:await Promise.all(assets.map(async filename=>({filename,sha256:await hashFile(path.join(destination,filename))})))};
  await fs.promises.writeFile(path.join(destination,'MODEL.json'),`${JSON.stringify(manifest,null,2)}\n`);
  console.log(`Local camera detector ready: ${CAMERA_MODEL.id}; ${CAMERA_MODEL.size} bytes; ${CAMERA_MODEL.sha256}`);
  return manifest;
}

if(process.argv[1]&&path.resolve(process.argv[1])===fileURLToPath(import.meta.url)){
  await prepareCameraDetector({download:process.argv.includes('--download')});
}

