#[tauri::command]
fn db_backup_json(
    app: AppHandle,
    auth: State<'_, AuthState>,
    session_token: String,
) -> Result<String, String> {
    require_role(&app, &auth, &session_token, Role::Admin)?;
    let conn = open_db(&app)?;
    let mut kv = serde_json::Map::new();
    let mut statement = conn
        .prepare("SELECT key,value FROM kv")
        .map_err(|e| e.to_string())?;
    let rows = statement
        .query_map([], |row| {
            Ok((row.get::<_, String>(0)?, row.get::<_, String>(1)?))
        })
        .map_err(|e| e.to_string())?;
    for row in rows {
        let (key, value) = row.map_err(|e| e.to_string())?;
        kv.insert(
            key,
            serde_json::from_str(&value).unwrap_or(serde_json::Value::String(value)),
        );
    }
    let users = users_list_internal(&conn)?;
    let mut audit_statement = conn
        .prepare("SELECT id,ts,user,action,details FROM audit ORDER BY id DESC LIMIT 2000")
        .map_err(|e| e.to_string())?;
    let audit = audit_statement
        .query_map([], |row| {
            Ok(AuditEntry {
                id: row.get(0)?,
                ts: row.get(1)?,
                user: row.get(2)?,
                action: row.get(3)?,
                details: row.get(4)?,
            })
        })
        .map_err(|e| e.to_string())?
        .collect::<Result<Vec<_>, _>>()
        .map_err(|e| e.to_string())?;
    serde_json::to_string_pretty(&serde_json::json!({
        "format": "klipper-farm-v18",
        "app_version": APP_VERSION,
        "created_at": now_ms(),
        "kv": kv,
        "users": users,
        "audit": audit
    }))
    .map_err(|e| e.to_string())
}

#[tauri::command]
fn db_restore_json(
    app: AppHandle,
    auth: State<'_, AuthState>,
