          <article className="printing"><i><Printer/></i><span>Печатают</span><strong>{printing}</strong></article>
          <article className={attentionCount?'attention':'healthy'}><i>{attentionCount?<AlertTriangle/>:<CheckCircle2/>}</i><span>Требует внимания</span><strong>{attentionCount}</strong></article>
          <article className="load"><i><Gauge/></i><span>Загрузка</span><strong>{loadPercent}%</strong></article>
        </div>}
      </header>

      {(engineRuntime.status==='failed'||engineRuntime.status==='embeddedFallback')&&<div className={`kfEngineNotice ${engineRuntime.status==='failed'?'failed':'fallback'}`} role="status">
        <AlertTriangle/>
        <div><b>{engineRuntime.status==='failed'?'Модуль связи восстанавливается':'Включён резервный движок связи'}</b><span>{engineRuntime.status==='failed'?'Ожидаем klipper-farmd; принтеры автоматически переключатся на защищённый встроенный движок.':'klipper-farmd не запустился, но локальная связь с принтерами продолжает работать через то же single-owner ядро.'}{engineRuntimeDetail?` Причина: ${engineRuntimeDetail}`:''}</span></div>
      </div>}

      {page==='dashboard'&&<FleetDashboard printers={printers} clients={clients.current} onOpen={setSelected} onPrinters={()=>navigate('printers')} onScan={scan} onReports={()=>navigate('history')}/>} 

      {page==='printers'&&<section className="kfPrinterGrid">
        {printers.map((p,i)=><div className="kfCardWrap" key={p.id}>
          <PrinterCard index={i+1} p={p} onAction={action} onOpen={setSelected} onCamera={setCamera} onFiles={setFilesPrinterId} onSettings={isAdmin?setSettings:undefined}/>
          {isAdmin&&<button type="button" className="kfDelete" title={`Удалить принтер «${p.name}»`} aria-label={`Удалить принтер «${p.name}»`} onClick={()=>remove(p.id)}><Trash2/></button>}
        </div>)}
      </section>}

      {page==='printers'&&!printers.length&&<div className="kfEmpty"><Printer size={64}/><h2>Добавьте первый принтер</h2><button onClick={scan}><Radar/>Найти в сети</button></div>}

      {page==='tools'&&<section className="kfToolsPage">
        <button disabled={!isAdmin} onClick={scan}><span><Radar/></span><div><b>Найти принтеры</b><small>Автоматический поиск Moonraker в локальной сети</small></div></button>
        <button disabled={!canOperate} onClick={()=>{setPage('queue');setQueue(true)}}><span><ListOrdered/></span><div><b>Очередь</b><small>Загрузка и порядок заданий для всех принтеров</small></div></button>
        <button disabled={!canOperate} onClick={()=>setDispatch(true)}><span><Bot/></span><div><b>Диспетчер</b><small>Автоматическое распределение печати по ферме</small></div></button>
        <button disabled={!canOperate} onClick={()=>{setPage('files');setProduction(true)}}><span><Factory/></span><div><b>Производство</b><small>G-code, расписание, катушки и себестоимость</small></div></button>
        <button disabled={!canOperate} onClick={()=>setMaintenance(true)}><span><Wrench/></span><div><b>Обслуживание</b><small>Сопло, оси, ремни и регламент Ender-3 V3 KE</small></div></button>
        <button onClick={()=>setHealth(true)}><span><Shield/></span><div><b>Самодиагностика</b><small>Moonraker, Klipper, MCU, нагреватели, камера и конфигурация</small></div></button>
        <button onClick={()=>setTv(true)}><span><MonitorUp/></span><div><b>TV-панель</b><small>Полноэкранный мониторинг состояния фермы</small></div></button>
        <button disabled={!canOperate} onClick={()=>setCameraGuardOpen(true)}><span><Shield/></span><div><b>Контроль камеры</b><small>Распознавание «каши», уведомления и автопауза</small></div></button>
      </section>}
    </main>

    <NotificationToastHost/>
    {canOperate&&printerConfigReady&&<CameraGuardHost printers={printers} clients={clients.current} controller={cameraGuardController}/>}
    {selectedPrinter&&<ControlPanel
      printer={selectedPrinter}
      client={clients.current.get(selectedPrinter.id)}
      onClose={()=>setSelected(undefined)}
      onNavigate={destination=>navigate(destination)}
      onSettings={isAdmin?()=>{
        setSelected(undefined);
        setSettings(selectedPrinter.id);
      }:undefined}
    />} 
    {cameraPrinter&&<CameraModal printer={cameraPrinter} onClose={()=>setCamera(undefined)}/>} 
    {filesPrinter&&<PrinterFilesPanel printer={filesPrinter} printers={printers} client={clients.current.get(filesPrinter.id)} canOperate={canOperate} onClose={()=>setFilesPrinterId(undefined)}/>} 
    {queue&&<QueuePanel printers={printers} clients={clients.current} canOperate={canOperate} onClose={()=>navigate('dashboard')}/>} 
    {settingsPrinter&&isAdmin&&<PrinterSettings printer={settingsPrinter} onSave={updateConfig} onDelete={()=>remove(settingsPrinter.id)} onClose={()=>setSettings(undefined)}/>} 
    {analytics&&<AnalyticsPanel printers={printers} clients={clients.current} onClose={()=>navigate('dashboard')}/>} 
    {dispatch&&<AutoDispatchPanel printers={printers} clients={clients.current} onClose={()=>setDispatch(false)}/>}
    {production&&<ProductionPanel printers={printers} clients={clients.current} onClose={()=>navigate('dashboard')}/>} 
    {maintenance&&<MaintenancePanel printers={printers} controller={maintenanceController} onClose={()=>setMaintenance(false)}/>} 
    {health&&<FleetHealthPanel printers={printers} clients={clients.current} onClose={()=>setHealth(false)}/>} 
    {tv&&<TvDashboard printers={printers} maintenance={maintenanceController.state} cameraWatch={cameraGuardController.statuses} onOpenCameraWatch={canOperate?()=>{setTv(false);setCameraGuardOpen(true)}:undefined} onClose={()=>setTv(false)}/>}
    {cameraGuardOpen&&<CameraGuardPanel printers={printers} controller={cameraGuardController} canOperate={canOperate} onClose={()=>setCameraGuardOpen(false)}/>}
    {system&&isAdmin&&<SystemPanel onClose={()=>navigate('dashboard')} onLogout={onLogout} printing={printers.some(p=>printerBlocksUpdate(p.status))}/>} 
    {isAdmin&&<DiscoveryPanel open={showDiscovery} printers={printers} onClose={()=>setShowDiscovery(false)} onAdd={addDiscovered} onAddAll={addAllDiscovered}/>} 
  </div>
}

export default function App(){
 const [session,setSession]=useState<AuthSession>(),[needsSetup,setNeedsSetup]=useState(false),[loading,setLoading]=useState(true),[error,setError]=useState('');
 useEffect(()=>{getAuthStatus().then(status=>setNeedsSetup(status.needsSetup)).catch(value=>setError(String(value))).finally(()=>setLoading(false))},[]);
 useEffect(()=>{const expired=()=>{setAuthSession();setSession(undefined)};window.addEventListener('klipper-auth-required',expired);return()=>window.removeEventListener('klipper-auth-required',expired)},[]);
 const authenticated=(value:AuthSession)=>{setAuthSession(value);setSession(value)};
 const signOut=()=>{logout().finally(()=>setSession(undefined))};
 if(loading)return <main className="authScreen"><section className="authCard"><h1>Klipper Farm</h1><p>Проверка защищённого профиля…</p></section></main>;
 if(error)return <main className="authScreen"><section className="authCard"><h1>Ошибка запуска</h1><div className="authError">{error}</div></section></main>;
 if(!session)return <LoginPanel needsSetup={needsSetup} onAuthenticated={authenticated}/>;
 return <FarmApp session={session} onLogout={signOut}/>;
}

import {useEffect,useRef,useState} from 'react';
import type {PrinterModel} from '../types';
import type {MoonrakerClient} from '../lib/moonraker';
import type {CameraGuardController} from '../lib/cameraGuardRuntime';
import {cameraGuardSource,prepareCameraFrame,type CameraGuardSource} from '../lib/cameraFrames';
import {secureInvoke} from '../lib/auth';
import {isK1Max} from './PrinterCamera';

const FRAME_INTERVAL=8_000;
const reasonText=(reason:unknown)=>String(reason instanceof Error?reason.message:reason).slice(0,200);
const encodeOffer=(offer:unknown)=>btoa(JSON.stringify(offer));
const decodeAnswer=(value:string)=>JSON.parse(new TextDecoder().decode(Uint8Array.from(atob(value.trim()),c=>c.charCodeAt(0)))) as RTCSessionDescriptionInit;

/** Lives with FarmApp, independently of the TV view and camera dialogs. */
export function CameraGuardHost({printers,clients,controller}:{printers:PrinterModel[];clients:Map<string,MoonrakerClient>;controller:CameraGuardController}){
  const active=new Set(controller.activePrinterIds);
  return <div className="cameraGuardSources" aria-hidden="true" style={{position:'fixed',left:-2_000,top:0,width:2,height:2,overflow:'hidden',pointerEvents:'none'}}>
    {printers.filter(printer=>active.has(printer.id)).map(printer=>{
      const source=cameraGuardSource(printer);
      return <CameraFrameSource key={JSON.stringify([printer.id,printer.host,printer.profile?.preset,printer.name,source])} printer={printer} client={clients.get(printer.id)} source={source} controller={controller}/>;
    })}
  </div>;
}

function CameraFrameSource({printer,client,source,controller}:{printer:PrinterModel;client?:MoonrakerClient;source?:CameraGuardSource;controller:CameraGuardController}){
  const latest=useRef({printer,client,controller});latest.current={printer,client,controller};
  const video=useRef<HTMLVideoElement>(null);
  const [retry,setRetry]=useState(0);
  useEffect(()=>{
    let stopped=false,busy=false,lastHash='',lastFrameToken='',lastCaptured=Date.now(),lastAttempt=0;
    let finishIce:(()=>void)|undefined;
    let timer:number|undefined,watchdog:number|undefined,frameHandle:number|undefined,retryTimer:number|undefined;
    let peer:RTCPeerConnection|undefined;
    const epoch=crypto.randomUUID(),element=video.current;
    const unavailable=(reason:string)=>{if(!stopped)latest.current.controller.unavailable(printer.id,reason)};
    // Invalidate inference from the previous camera immediately, before a new
    // snapshot or WebRTC handshake can finish and provide its first frame.
    unavailable('Камера подключается — ждём свежий кадр');
    const reconnect=()=>{if(!stopped&&retryTimer===undefined)retryTimer=window.setTimeout(()=>{if(!stopped)setRetry(value=>value+1)},15_000)};
    const capture=async(image:CanvasImageSource,width:number,height:number,token:string,capturedAt:number,jobToken:string)=>{
      const frame=await prepareCameraFrame(image,width,height);
      if(stopped||latest.current.controller.getJobToken(printer.id)!==jobToken){frame.bitmap.close();return;}
      if(frame.hash===lastHash||token===lastFrameToken){frame.bitmap.close();unavailable('Кадр не изменился — ждём новое изображение');return;}
      lastHash=frame.hash;lastFrameToken=token;lastCaptured=capturedAt;
      latest.current.controller.submitFrame(printer.id,frame.bitmap,{capturedAt,frameToken:token+':'+frame.hash,sourceEpoch:epoch,jobToken});
    };
    const snapshot=async()=>{
      if(stopped||!source||source.kind!=='snapshot')return;
      const context=latest.current,jobToken=context.controller.getJobToken(printer.id);
      if(jobToken&&context.client&&!busy){
        busy=true;const started=Date.now();
        try{
          const response=await context.client.snapshot(source.url);
          if(stopped)return;
          if(Date.now()-started>FRAME_INTERVAL)throw new Error('Камера ответила слишком поздно — кадр пропущен');
          if(response.status<200||response.status>=300||!response.contentType?.toLowerCase().startsWith('image/')||!response.body.length)throw new Error('Камера не передала изображение');
          const bitmap=await createImageBitmap(new Blob([new Uint8Array(response.body)],{type:response.contentType}));
          try{await capture(bitmap,bitmap.width,bitmap.height,crypto.randomUUID(),Date.now(),jobToken)}finally{bitmap.close()}
        }catch(reason){unavailable(reasonText(reason))}finally{busy=false}
      }
      if(!stopped)timer=window.setTimeout(()=>void snapshot(),FRAME_INTERVAL);
    };
    const startVideo=async()=>{
      if(!element)return;
      peer=new RTCPeerConnection({iceServers:[]});
      const transceiver=peer.addTransceiver('video',{direction:isK1Max(printer)?'sendrecv':'recvonly'});
      const codecs=RTCRtpReceiver.getCapabilities?.('video')?.codecs;
      if(codecs?.length&&transceiver.setCodecPreferences){const h264=codecs.filter(c=>c.mimeType.toLowerCase()==='video/h264');transceiver.setCodecPreferences([...h264,...codecs.filter(c=>c.mimeType.toLowerCase()!=='video/h264')]);}
      peer.ontrack=event=>{
        if(stopped||!element)return;
        element.srcObject=event.streams[0]||new MediaStream([event.track]);
        void element.play().catch(()=>unavailable('Не удалось начать чтение видеокадров'));
      };
      peer.onconnectionstatechange=()=>{if(peer&&(peer.connectionState==='failed'||peer.connectionState==='disconnected')){unavailable('Поток камеры прерван — анализ не выполняется');reconnect()}};
      const offer=await peer.createOffer();await peer.setLocalDescription(offer);
      await new Promise<void>(resolve=>{
        if(!peer||peer.iceGatheringState==='complete')return resolve();
        const pc=peer,finish=()=>{pc.removeEventListener('icegatheringstatechange',done);finishIce=undefined;resolve()},done=()=>{if(pc.iceGatheringState==='complete')finish()};
        finishIce=finish;
        pc.addEventListener('icegatheringstatechange',done);
        timer=window.setTimeout(finish,2_500);
      });
      if(stopped||!peer)return;
      const raw=await secureInvoke<string>('creality_webrtc_offer',{printerId:printer.id,host:printer.host,offer:encodeOffer({type:'offer',sdp:peer.localDescription?.sdp||offer.sdp})});
      if(stopped||!peer)return;
      const answer=decodeAnswer(raw);if(answer.type!=='answer'||!answer.sdp)throw new Error('Камера не вернула видеопоток');
      await peer.setRemoteDescription(answer);
      const tick:VideoFrameRequestCallback=(_now,metadata)=>{
        if(stopped||!element)return;
        frameHandle=element.requestVideoFrameCallback(tick);
        const current=latest.current,jobToken=current.controller.getJobToken(printer.id),at=Date.now();
        if(!jobToken||busy||at-lastAttempt<FRAME_INTERVAL||element.readyState<2||!element.videoWidth)return;
        busy=true;lastAttempt=at;
        void capture(element,element.videoWidth,element.videoHeight,`${metadata.presentedFrames}:${metadata.mediaTime}`,at,jobToken).catch(reason=>unavailable(reasonText(reason))).finally(()=>{busy=false});
      };
      if(typeof element.requestVideoFrameCallback!=='function')throw new Error('Требуется обновление WebView2 для чтения видеокадров');
      frameHandle=element.requestVideoFrameCallback(tick);
    };
    if(!source)unavailable('У камеры нет адреса снимков для анализа');
    else if(source.kind==='snapshot')void snapshot();
    else void startVideo().catch(reason=>{unavailable(reasonText(reason));reconnect()});
    watchdog=window.setInterval(()=>{if(source?.kind==='webrtc'&&Date.now()-lastCaptured>25_000){unavailable('Нет свежих видеокадров — анализ не выполняется');reconnect()}},10_000);
    return()=>{
      stopped=true;if(timer!==undefined)window.clearTimeout(timer);finishIce?.();if(watchdog!==undefined)window.clearInterval(watchdog);if(retryTimer!==undefined)window.clearTimeout(retryTimer);
      if(element){if(frameHandle!==undefined&&typeof element.cancelVideoFrameCallback==='function')element.cancelVideoFrameCallback(frameHandle);element.pause();element.srcObject=null;}
      if(peer){peer.ontrack=null;peer.onconnectionstatechange=null;peer.close();}
    };
  },[printer.id,printer.host,JSON.stringify(source),retry]);
  return source?.kind==='webrtc'?<video ref={video} autoPlay muted playsInline/>:null;
}

