import {Camera,ShieldCheck,ShieldAlert,X,RefreshCw} from 'lucide-react';
import type {PrinterModel} from '../types';
import type {CameraGuardController} from '../lib/cameraGuardRuntime';
import {cameraGuardSource} from '../lib/cameraFrames';
import {useModalAccessibility} from '../lib/modalAccessibility';
import './CameraGuardPanel.css';

export function CameraGuardPanel({printers,controller,onClose,canOperate=true}:{printers:PrinterModel[];controller:CameraGuardController;onClose:()=>void;canOperate?:boolean}){
  useModalAccessibility(onClose,'.cameraGuardPanel','Контроль печати по камере');
  return <div className="modalBackdrop"><section className="panel cameraGuardPanel">
    <header className="panelHead"><div><h2><ShieldCheck/> Контроль печати по камере</h2><p>Обнаружение «каши» и автопауза для выбранных принтеров.</p></div><button className="round" aria-label="Закрыть контроль камеры" onClick={onClose}><X/></button></header>
    <div className="cameraGuardBody">
      <div className="cameraGuardIntro"><Camera/><div><b>Кадры анализируются локально на этом ПК</b><p>Выбери режим для каждого принтера. Анализ начинается после первой минуты печати и работает при открытой программе, даже когда TV-панель закрыта.</p><small>Подозрение подтверждается на нескольких разных свежих кадрах. Ракурс и освещение влияют на распознавание; модель ищет видимые признаки «каши».</small></div></div>
      <div className="cameraGuardModes"><div><b>Уведомлять</b><span>Сообщить о подозрении, чтобы ты проверил печать.</span></div><div><b>Автопауза</b><span>При подтверждённом подозрении запросить паузу и проверить ответ принтера. Возобновление — вручную.</span></div></div>
      {controller.error&&<div className="cameraGuardError" role="alert"><span>{controller.error}</span><button onClick={controller.retry}><RefreshCw/>Повторить</button></div>}
      {!controller.ready&&!controller.error&&<p role="status">Загрузка настроек камер…</p>}
      <div className="cameraGuardPrinterList">{printers.map(printer=>{
        const source=cameraGuardSource(printer),mode=controller.settings.printers[printer.id]?.mode??'off',status=controller.statuses[printer.id];
        return <article key={printer.id} className={`cameraGuardPrinter ${status?.tone??'neutral'}`}>
          <div className="cameraGuardPrinterName"><Camera/><div><b>{printer.name}</b><small>{source?.label??'Для анализа нужен адрес снимков камеры или встроенная камера Creality'}</small></div></div>
          <label>Режим контроля<select aria-label={`Контроль камеры: ${printer.name}`} value={mode} disabled={!controller.ready||!canOperate} onChange={event=>void controller.setMode(printer.id,event.target.value as 'off'|'notify'|'pause')}><option value="off">Выключено</option><option value="notify" disabled={!source}>Уведомлять</option><option value="pause" disabled={!source||printer.capabilities?.canPause===false}>Автопауза</option></select></label>
          <div className="cameraGuardPrinterStatus" role="status">{status?.tone==='danger'?<ShieldAlert/>:<ShieldCheck/>}<span>{status?.label??(mode==='off'?'Контроль выключен':'Ожидание данных принтера')}</span></div>
        </article>;
      })}</div>
      {!printers.length&&<div className="cameraGuardEmpty"><Camera/><b>Добавь принтер с камерой</b><span>Здесь появятся настройки контроля для каждого принтера.</span></div>}
    </div>
  </section></div>;
}

import { useEffect, useMemo, useRef, useState } from 'react';
import { createPortal } from 'react-dom';
import { AlertTriangle, Bell, CheckCheck, CheckCircle2, CircleDot, PlugZap, RefreshCw, X } from 'lucide-react';
import type { PrinterModel } from '../types';
import { notificationList, type AuditEntry } from '../lib/db';
import { NotificationTest } from './NotificationTest';
import { NOTIFICATION_REFRESH } from '../lib/appNotifications';
import { diagnosticWarning } from '../lib/diagnosticLog';
import { useModalAccessibility } from '../lib/modalAccessibility';

const labels:Record<string,string>={
  'camera.warning':'Камера: подозрение на «кашу»','camera.paused':'Печать приостановлена по камере','camera.pause_failed':'Пауза по камере не подтверждена',
  'notification.test':'Проверка уведомлений','update.available':'Доступно обновление','update.current':'Проверка обновлений завершена','update.error':'Ошибка обновления',
  'print.complete':'Печать завершена','print.cancelled':'Печать отменена','printer.error':'Ошибка принтера','printer.offline':'Принтер потерял связь','printer.online':'Связь восстановлена','filament.runout':'Закончился филамент','print.dispatch':'Задание отправлено','print.validated_start':'Печать запущена','print.queue_add':'Добавлено в очередь','queue.auto_start':'Очередь запущена автоматически','queue.manual_start':'Очередь запущена','queue.auto_blocked':'Автозапуск очереди остановлен','queue.start_blocked':'Запуск очереди заблокирован','gcode.blocked':'G-code заблокирован','schedule.blocked':'Запуск по расписанию заблокирован','maintenance.complete':'Обслуживание выполнено','maintenance.due':'Пора выполнить обслуживание','diagnostics.complete':'Диагностика завершена','history.snapshot_saved':'Снимок сохранён',
};
const tone=(action:string)=>/error|offline|blocked|runout|camera\.warning|camera\.pause_failed/.test(action)?'danger':/complete|online|snapshot/.test(action)?'success':'info';

export function NotificationCenter({printers,userId,onOpenPrinter}:{printers:PrinterModel[];userId:string;onOpenPrinter:(id:string)=>void}){
  const [open,setOpen]=useState(false),[entries,setEntries]=useState<AuditEntry[]>([]),[busy,setBusy]=useState(false),[error,setError]=useState('');
  useModalAccessibility(()=>setOpen(false),'.notificationDrawer','Центр уведомлений',open);
  const root=useRef<HTMLDivElement>(null),drawer=useRef<HTMLElement>(null),refreshInFlight=useRef<Promise<void>>();
  const key=`klipper-notifications-read-id-v2-${userId}`;
  const markerExists=useRef(localStorage.getItem(key)!==null),initialised=useRef(false);
  const [lastReadId,setLastReadId]=useState(()=>{const value=Number(localStorage.getItem(key)||0);return Number.isFinite(value)&&value>0?value:0});
  const saveReadId=(value:number)=>{try{localStorage.setItem(key,String(value))}catch(error){diagnosticWarning('notifications.read_marker',error)}setLastReadId(value);markerExists.current=true};
  const latestId=(items=entries)=>items.reduce((latest,entry)=>Math.max(latest,entry.id),0);
  const refresh=()=>{
    if(refreshInFlight.current)return refreshInFlight.current;
    const task=(async()=>{setBusy(true);try{const next=await notificationList(120);setEntries(next);setError('');if(!initialised.current){initialised.current=true;if(!markerExists.current)saveReadId(latestId(next))}}catch(error){setError('Не удалось загрузить уведомления: '+String(error instanceof Error?error.message:error))}finally{setBusy(false)}})();
    refreshInFlight.current=task;
    void task.finally(()=>{if(refreshInFlight.current===task)refreshInFlight.current=undefined}).catch(()=>{});
    return task;
  };
  useEffect(()=>{let stopped=false,timer:number|undefined;const loop=async()=>{try{await refresh()}catch(error){diagnosticWarning('notifications.refresh',error)}finally{if(!stopped)timer=window.setTimeout(loop,8_000)}};void loop();return()=>{stopped=true;if(timer)window.clearTimeout(timer)}},[]);
  useEffect(()=>{const updated=()=>void refresh();window.addEventListener(NOTIFICATION_REFRESH,updated);return()=>window.removeEventListener(NOTIFICATION_REFRESH,updated)},[]);
  useEffect(()=>{if(!open)return;const pointer=(event:PointerEvent)=>{const target=event.target as Node;if(!root.current?.contains(target)&&!drawer.current?.contains(target))setOpen(false)},key=(event:KeyboardEvent)=>{if(event.key==='Escape')setOpen(false)};document.addEventListener('pointerdown',pointer);document.addEventListener('keydown',key);return()=>{document.removeEventListener('pointerdown',pointer);document.removeEventListener('keydown',key)}},[open]);
  const unread=useMemo(()=>entries.filter(entry=>entry.id>lastReadId).length,[entries,lastReadId]);
  const markRead=()=>saveReadId(latestId());
  const toggle=()=>{if(open){setOpen(false);return}setOpen(true);markRead();void refresh()};
  const openEntry=(entry:AuditEntry)=>{const printer=printers.find(item=>entry.details.includes(item.id)||entry.details.toLowerCase().includes(item.name.toLowerCase())||entry.details.includes(item.host));if(printer){onOpenPrinter(printer.id);setOpen(false)}};
  return <div className="notificationCenter" ref={root}>
    <button type="button" className="notificationBell" title="Уведомления" aria-label={`Уведомления${unread?`: ${unread} непрочитанных`:''}`} aria-expanded={open} aria-controls="notification-drawer" onClick={toggle}><Bell/>{unread>0&&<b>{unread>9?'9+':unread}</b>}</button>
    {open&&createPortal(<><div className="notificationScrim" aria-hidden="true" onClick={()=>setOpen(false)}/><section id="notification-drawer" ref={drawer} className="notificationDrawer" role="dialog" aria-modal="true" aria-label="Центр уведомлений"><header><div><Bell/><span><b>Уведомления</b><small>{entries.length?`${entries.length} последних событий`:'Новых событий нет'}</small></span></div><div><button type="button" title="Обновить" aria-label="Обновить уведомления" disabled={busy} onClick={()=>void refresh()}><RefreshCw className={busy?'spin':''}/></button><button type="button" title="Отметить прочитанными" onClick={markRead}><CheckCheck/></button><button type="button" title="Закрыть" aria-label="Закрыть уведомления" onClick={()=>setOpen(false)}><X/></button></div></header><div className="notificationList">{error&&<p className="notificationLoadError" role="alert">{error}</p>}{busy&&!entries.length&&<p role="status">Загрузка уведомлений…</p>}{entries.map(entry=>{const kind=tone(entry.action),Icon=entry.action.includes('online')?PlugZap:kind==='danger'?AlertTriangle:kind==='success'?CheckCircle2:CircleDot;const hasPrinter=printers.some(item=>entry.details.includes(item.id)||entry.details.toLowerCase().includes(item.name.toLowerCase())||entry.details.includes(item.host));return <article className={`${kind} ${entry.id>lastReadId?'unread':''}`} key={entry.id}><i><Icon/></i><span><b>{labels[entry.action]??entry.action.replace(/[._]/g,' ')}</b><small>{entry.details||entry.user}</small><time>{new Date(entry.ts).toLocaleString()}</time></span>{hasPrinter&&<button type="button" onClick={()=>openEntry(entry)}>Открыть принтер</button>}</article>})}{!entries.length&&!busy&&!error&&<div className="notificationEmpty"><CheckCircle2/><b>Всё спокойно</b><span>Ошибки, завершения печати и обрывы связи появятся здесь.</span></div>}</div><footer><NotificationTest/></footer></section></>,document.body)}
  </div>;
}

