type CameraWatch=Record<string,{label:string;tone:'neutral'|'success'|'warning'|'danger'}>;
type Props={printers:PrinterModel[];onClose:()=>void;maintenance?:MaintenanceState;cameraWatch?:CameraWatch;onOpenCameraWatch?:()=>void};
const summaryLabels={printing:'Печатает',ready:'Готово',paused:'Пауза',error:'Ошибки',offline:'Нет связи',unknown:'Нет данных'};

function TvPrinter({printer,now,cameras,maintenance,watch}:{printer:PrinterModel;now:number;cameras:boolean;maintenance?:MaintenanceState;watch?:CameraWatch[string]}){
  const card=useRef<HTMLElement>(null);
  const [visible,setVisible]=useState(true),[cameraFailed,setCameraFailed]=useState(false),[cameraAttempt,setCameraAttempt]=useState(0);
  const cameraSource=JSON.stringify([printer.name,printer.host,printer.webcams,printer.profile?.preset]);
  useEffect(()=>{setCameraFailed(false)},[cameraSource]);
  useEffect(()=>{
    if(!card.current||typeof IntersectionObserver==='undefined')return;
    const observer=new IntersectionObserver(entries=>setVisible(entries.some(entry=>entry.isIntersecting)),{threshold:.05});
    observer.observe(card.current);return()=>observer.disconnect();
  },[]);
  const state=tvPrinterState(printer,now),freshness=tvFreshness(printer,now),progress=tvProgress(printer,now),remaining=tvRemainingSeconds(printer,now),due=tvDueTasks(printer.id,maintenance);
  const active=state==='printing'||state==='paused';
  const temperatureAvailable=state!=='offline'&&!printer.status.remoteControlSuspended;
  const filename=progress===undefined?'Данные задания недоступны':printer.status.filename||(state==='ready'?'Ожидает задание':'Нет активного задания');
  const hasCamera=hasPrinterCamera(printer),showCamera=cameras&&hasCamera&&!cameraFailed&&state!=='offline';
  return <article ref={card} className={`tvPrinter state-${state}${showCamera?' with-camera':''}`} aria-label={`${printer.name}: ${TV_STATE_LABELS[state]}`}>
    <header className="tvPrinterHead"><div><span className="tvPrinterName" title={printer.name}>{printer.name}</span><span className="tvPrinterHost">{printer.host}</span></div><span className={`tvPrinterStatus state-${state}`}><i/>{printer.status.remoteControlSuspended?'Автономная печать':TV_STATE_LABELS[state]}</span></header>
    {showCamera&&<div className="tvPrinterCamera"><PrinterCamera key={cameraAttempt} printer={printer} active={visible} onAvailability={available=>{if(!available)setCameraFailed(true)}}/></div>}
    <div className="tvPrinterJob"><span>{active?'Текущее задание':state==='ready'&&printer.status.filename?'Последнее задание':'Задание'}</span><strong title={filename}>{filename}</strong></div>
    <div className="tvPrinterProgress"><strong>{active&&progress!==undefined?`${progress}%`:'—'}</strong><span><Clock3/>{remaining!==undefined?`≈ ${tvDuration(remaining)} осталось`:state==='paused'?'Оценка после продолжения':active&&progress===100?'Завершение печати':active?'Оценка времени пока недоступна':state==='ready'?'Готов к работе':'Нет свежей оценки'}</span></div>
    <div className="tvProgressTrack" role="progressbar" aria-label={`Прогресс ${printer.name}`} aria-valuemin={0} aria-valuemax={100} aria-valuenow={active?progress:undefined}><i style={{width:`${active?progress??0:0}%`}}/></div>
    <div className="tvTemperatures"><div><Thermometer/><span>Сопло</span><strong>{temperatureAvailable?confirmedTemperature(printer.status.nozzle,printer.status,now):'—'}</strong></div><div><Thermometer/><span>Стол</span><strong>{temperatureAvailable?confirmedTemperature(printer.status.bed,printer.status,now):'—'}</strong></div></div>
    <footer className="tvPrinterFoot"><span className={`tvFreshness ${freshness.tone}`}><i/>{freshness.label}</span>{due.length>0&&<span className="tvServiceDue" title={due.map(task=>task.title).join(' · ')}><Wrench/>Обслуживание · {due.length}</span>}{watch&&<span className={`tvCameraWatch tone-${watch.tone}`}><Camera/>{watch.label}</span>}{cameras&&cameraFailed&&<button className="tvCameraRetry" onClick={()=>{setCameraFailed(false);setCameraAttempt(value=>value+1)}}>Камера недоступна · повторить</button>}{cameras&&!hasCamera&&<span className="tvNoCamera">Камера не настроена</span>}</footer>
  </article>;
}

export function TvDashboard({printers,onClose,maintenance,cameraWatch,onOpenCameraWatch}:Props){
  const now=useLiveNow(),root=useRef<HTMLDivElement>(null),onCloseRef=useRef(onClose),wasFullscreen=useRef(false),manualFullscreenExit=useRef(false);
  onCloseRef.current=onClose;
  const [viewport,setViewport]=useState(()=>({width:window.innerWidth,height:window.innerHeight}));
  const [page,setPage]=useState(0),[cameras,setCameras]=useState(false),[fullscreen,setFullscreen]=useState(false),[documentVisible,setDocumentVisible]=useState(!document.hidden),[fullscreenMessage,setFullscreenMessage]=useState('');
  const layout=tvLayout(viewport.width,viewport.height),pages=Math.max(1,Math.ceil(printers.length/layout.pageSize)),currentPage=Math.min(page,pages-1);
  const visiblePrinters=printers.slice(currentPage*layout.pageSize,(currentPage+1)*layout.pageSize);
  const rows=Math.max(1,Math.ceil(visiblePrinters.length/layout.columns));
  const notices=tvNotices(printers,now,maintenance),counts=tvSummary(printers,now);
  for(const printer of printers){
    const watch=cameraWatch?.[printer.id];
    if(watch&&(watch.tone==='warning'||watch.tone==='danger'))notices.push({id:`camera:${printer.id}`,printerId:printer.id,printerName:printer.name,label:'Контроль камеры',detail:watch.label,tone:watch.tone,priority:watch.tone==='danger'?0:3});
  }
  notices.sort((a,b)=>a.priority-b.priority);
  useEffect(()=>{
    const previousFocus=document.activeElement instanceof HTMLElement?document.activeElement:undefined;
    const previousOverflow=document.body.style.overflow;
    const element=root.current;
    document.body.style.overflow='hidden';element?.focus();
    const resize=()=>setViewport({width:window.innerWidth,height:window.innerHeight});
    const visibility=()=>setDocumentVisible(!document.hidden);
    const full=()=>{
      const active=document.fullscreenElement===element;
      if(!active&&wasFullscreen.current&&!manualFullscreenExit.current)onCloseRef.current();
      wasFullscreen.current=active;manualFullscreenExit.current=false;setFullscreen(active);
    };
    const key=(event:KeyboardEvent)=>{
      if(event.key==='Escape'){event.preventDefault();event.stopPropagation();onCloseRef.current();}
      if(event.key==='Tab'&&element){
        const controls=Array.from(element.querySelectorAll<HTMLElement>('button:not([disabled]),[tabindex="0"]'));
        const first=controls[0],last=controls[controls.length-1];
        if(event.shiftKey&&(document.activeElement===first||document.activeElement===element)){event.preventDefault();last?.focus();}
        else if(!event.shiftKey&&document.activeElement===last){event.preventDefault();first?.focus();}
      }
    };
    window.addEventListener('resize',resize);document.addEventListener('visibilitychange',visibility);document.addEventListener('fullscreenchange',full);document.addEventListener('keydown',key,true);
    return()=>{window.removeEventListener('resize',resize);document.removeEventListener('visibilitychange',visibility);document.removeEventListener('fullscreenchange',full);document.removeEventListener('keydown',key,true);document.body.style.overflow=previousOverflow;if(document.fullscreenElement===element)void document.exitFullscreen().catch(()=>{});previousFocus?.focus();};
  },[]);
  useEffect(()=>{setPage(value=>Math.min(value,pages-1))},[pages]);
  const toggleFullscreen=async()=>{
    setFullscreenMessage('');
    try{if(document.fullscreenElement===root.current){manualFullscreenExit.current=true;await document.exitFullscreen();}else if(root.current?.requestFullscreen)await root.current.requestFullscreen();else setFullscreenMessage('Полный экран недоступен. Панель занимает всё окно программы.');}
    catch{manualFullscreenExit.current=false;setFullscreenMessage('Полный экран недоступен. Панель занимает всё окно программы.');}
  };
  return <div ref={root} className={`tvDashboard${cameras?' tvShowCameras':''}`} role="dialog" aria-modal="true" aria-label="TV-панель фермы" tabIndex={-1} style={{'--tv-columns':layout.columns,'--tv-rows':rows} as CSSProperties}>
    <header className="tvDashboardHead"><div className="tvDashboardBrand"><Monitor/><div><h1>Ферма на экране</h1><span>{printers.length} принтеров · TV-панель</span></div></div><div className="tvDashboardClock"><strong>{new Date(now).toLocaleTimeString('ru-RU',{hour:'2-digit',minute:'2-digit'})}</strong><span>{new Date(now).toLocaleDateString('ru-RU',{day:'numeric',month:'long'})}</span></div><div className="tvDashboardActions"><button aria-pressed={cameras} onClick={()=>setCameras(value=>!value)}><Camera/><span>{cameras?'Показатели':'Камеры'}</span></button>{onOpenCameraWatch&&<button onClick={onOpenCameraWatch}><AlertTriangle/><span>Контроль камер</span></button>}<button onClick={()=>void toggleFullscreen()} aria-label={fullscreen?'Выйти из полного экрана':'На весь экран'} title={fullscreen?'Выйти из полного экрана':'На весь экран'}>{fullscreen?<Minimize2/>:<Maximize2/>}</button><button onClick={onClose} aria-label="Закрыть TV-панель" title="Закрыть TV-панель · Esc"><X/></button></div></header>
    <section className="tvSummary" aria-label="Сводка фермы">{TV_STATES.map(state=><div key={state} className={`state-${state}`}><strong>{counts[state]}</strong><span>{summaryLabels[state]}</span></div>)}</section>
    <section className={`tvAttention${notices.length?'':' all-clear'}`} aria-label="Требует внимания"><div className="tvAttentionTitle">{notices.length?<AlertTriangle/>:<CheckCircle2/>}<strong>{notices.length?`Требует внимания · ${notices.length}`:'Всё спокойно'}</strong></div>{notices.length?<div className="tvNoticeList">{notices.map(notice=><article key={notice.id} className={`tone-${notice.tone}`} title={`${notice.printerName} · ${notice.label}: ${notice.detail}`}><strong>{notice.printerName}<span>{notice.label}</span></strong><p>{notice.detail}</p></article>)}</div>:<p>{printers.length?'Принтеры доступны, предупреждений нет':'Добавьте принтеры в основном окне программы'}</p>}</section>
    <main className="tvDashboardGrid" aria-label={`Принтеры, страница ${currentPage+1} из ${pages}`}>{visiblePrinters.length?visiblePrinters.map(printer=><TvPrinter key={printer.id} printer={printer} now={now} cameras={cameras&&documentVisible} maintenance={maintenance} watch={cameraWatch?.[printer.id]}/>):<div className="tvDashboardEmpty"><Printer/><h2>Пока нет принтеров</h2><p>После добавления принтеров здесь появится состояние всей фермы.</p><button onClick={onClose}>Вернуться к принтерам</button></div>}</main>
    <footer className="tvDashboardFoot"><span>{fullscreenMessage||'Обзор фермы · Esc — закрыть'}{cameras&&!documentVisible?' · Камеры приостановлены':''}</span>{pages>1&&<nav aria-label="Страницы принтеров"><button aria-label="Предыдущая страница" disabled={currentPage===0} onClick={()=>setPage(value=>Math.max(0,value-1))}><ChevronLeft/></button><strong>{currentPage+1} / {pages}</strong><button aria-label="Следующая страница" disabled={currentPage>=pages-1} onClick={()=>setPage(value=>Math.min(pages-1,value+1))}><ChevronRight/></button></nav>}<span className="tvEstimateNote">≈ время рассчитано по ходу печати</span></footer>
  </div>;
}

import type { CameraDetectionResult, CameraDetectorRequest, CameraDetectorResponse } from './cameraDetectorTypes';
export type { CameraDetectionResult, CameraFailureBox } from './cameraDetectorTypes';

type Request={id:number;frame?:ImageBitmap;resolve:(value:CameraDetectionResult)=>void;reject:(reason:Error)=>void;signal?:AbortSignal;abort:()=>void;enqueuedAt:number;settled?:boolean};
const MAX_QUEUED_FRAMES=8;
const MAX_QUEUE_AGE_MS=15_000;
const INITIALIZATION_DEADLINE_MS=120_000;
const INFERENCE_DEADLINE_MS=30_000;
let worker:Worker|undefined;
let active:Request|undefined;
let timer:ReturnType<typeof setTimeout>|undefined;
let initialized=false;
let nextId=0;
const queued:Request[]=[];

function settle(request:Request,error?:Error,result?:CameraDetectionResult){
  if(request.settled)return;
  request.settled=true;
  request.signal?.removeEventListener('abort',request.abort);
  request.frame?.close();
  request.frame=undefined;
  if(error)request.reject(error);else if(result)request.resolve(result);
}

function stop(error:Error){
  worker?.terminate();worker=undefined;initialized=false;
  if(timer)clearTimeout(timer);timer=undefined;
  const previous=active;active=undefined;
  if(previous)settle(previous,error);
  for(const request of queued.splice(0))settle(request,error);
}

function ensureWorker(){
  if(worker)return worker;
  const current=new Worker(new URL('./cameraDetectorWorker.ts',import.meta.url),{type:'module',name:'klipper-camera-detector'});
  worker=current;
  current.onmessage=({data}:MessageEvent<CameraDetectorResponse>)=>{
    if(worker!==current||!active||data.id!==active.id)return;
    if(timer)clearTimeout(timer);timer=undefined;
    const request=active;active=undefined;
    if(data.error)settle(request,new Error(data.error));
    else if(data.result&&Number.isFinite(data.result.score)&&data.result.score>=0&&data.result.score<=1){initialized=true;settle(request,undefined,data.result)}
    else settle(request,new Error('Модель вернула некорректный результат'));
    drain();
  };
  current.onerror=()=>{if(worker===current)stop(new Error('Модуль анализа камеры недоступен'))};
  current.onmessageerror=()=>{if(worker===current)stop(new Error('Не удалось получить результат анализа камеры'))};
  return current;
}

function drain(){
  if(active)return;
  while(queued.length){
    const request=queued.shift()!;
    if(request.signal?.aborted){settle(request,new Error('Анализ камеры отменён'));continue}
    if(Date.now()-request.enqueuedAt>MAX_QUEUE_AGE_MS){settle(request,new Error('Кадр устарел в очереди анализа'));continue}
    active=request;
    try{
      const current=ensureWorker();
      const frame=request.frame!;
      const assetBase=new URL('/camera-detector/',document.baseURI).href;
      timer=setTimeout(()=>stop(new Error('Истекло время анализа камеры')),initialized?INFERENCE_DEADLINE_MS:INITIALIZATION_DEADLINE_MS);
      const message:CameraDetectorRequest={id:request.id,frame,assetBase};
      current.postMessage(message,[frame]);
      request.frame=undefined;
    }catch(error){stop(error instanceof Error?error:new Error(String(error)))}
    return;
  }
}

/** Takes ownership of frame, including error/abort paths. All inference runs in one worker. */
export function analyzeCameraFrame(frame:ImageBitmap,signal?:AbortSignal):Promise<CameraDetectionResult>{
  if(signal?.aborted){frame.close();return Promise.reject(new Error('Анализ камеры отменён'))}
  if(queued.length>=MAX_QUEUED_FRAMES){frame.close();return Promise.reject(new Error('Очередь анализа камеры занята'))}
  return new Promise((resolve,reject)=>{
    const request:Request={id:++nextId,frame,resolve,reject,signal,enqueuedAt:Date.now(),abort:()=>{
      // A disappearing camera must not tear down the shared model or cancel
      // other printers. Its late result is ignored; the worker then drains.
      if(active===request){settle(request,new Error('Анализ камеры отменён'));return}
      const index=queued.indexOf(request);
      if(index>=0){queued.splice(index,1);settle(request,new Error('Анализ камеры отменён'))}
    }};
    signal?.addEventListener('abort',request.abort,{once:true});
    queued.push(request);drain();
  });
}

/** Terminates inference and releases its model and queued frames. Safe to initialize again. */
export function disposeCameraDetector(){stop(new Error('Анализ камеры остановлен'))}

/** Image coordinates are normalized to the analyzed frame, in [0, 1]. */
export interface CameraFailureBox { x:number; y:number; width:number; height:number; score:number }
export interface CameraDetectionResult {
  /** Highest model confidence for its single `failure` class; not a calibrated probability. */
  score:number;
  boxes:CameraFailureBox[];
  modelId:string;
}
export const CAMERA_DETECTOR_MODEL_ID='obico-failure-5a6b1be1fa';
export const CAMERA_DETECTOR_MODEL_FILE='obico-failure-5a6b1be1fa.onnx';
export type CameraDetectorRequest={id:number;frame:ImageBitmap;assetBase:string};
export type CameraDetectorResponse={id:number;result?:CameraDetectionResult;error?:string};

import * as ort from 'onnxruntime-web/wasm';
import { CAMERA_DETECTOR_MODEL_FILE, CAMERA_DETECTOR_MODEL_ID, type CameraDetectionResult, type CameraDetectorRequest, type CameraDetectorResponse, type CameraFailureBox } from './cameraDetectorTypes';

// Official Obico ONNX inference contract: RGB, linear 416x416 resize, NCHW /255.
// https://github.com/TheSpaghettiDetective/obico-server/blob/6f938964c63892df2b6d5b68d99ea783fc1a7c78/ml_api/lib/onnx.py
const SIDE=416;
const BOX_COUNT=845;
const CANDIDATE_THRESHOLD=0.08;
const NMS_IOU=0.45;
const MAX_BOXES=100;
const scope=self as unknown as {
  location:Location;
  onmessage:((event:MessageEvent<CameraDetectorRequest>)=>void)|null;
  postMessage:(message:CameraDetectorResponse)=>void;
};
let model:Promise<ort.InferenceSession>|undefined;
let modelBase:string|undefined;
let processing=false;

async function getModel(assetBase:string){
  const base=new URL(assetBase);
  if(base.origin!==scope.location.origin||!base.pathname.endsWith('/camera-detector/'))throw new Error('Некорректный путь локальной модели');
  if(modelBase&&modelBase!==base.href)throw new Error('Путь модели изменился во время анализа');
  if(!model){
    modelBase=base.href;
    ort.env.wasm.numThreads=1;
    ort.env.wasm.proxy=false;
    ort.env.wasm.wasmPaths={mjs:new URL('ort-wasm-simd-threaded.mjs',base).href,wasm:new URL('ort-wasm-simd-threaded.wasm',base).href};
    ort.env.logLevel='error';
    model=ort.InferenceSession.create(new URL(CAMERA_DETECTOR_MODEL_FILE,base).href,{executionProviders:['wasm'],graphOptimizationLevel:'all'}).then(session=>{
      const input=session.inputMetadata[0];
      if(session.inputNames.length!==1||session.inputNames[0]!=='input'||!input.isTensor||input.type!=='float32'||input.shape.join(',')!=='1,3,416,416'||session.outputNames.join(',')!=='boxes,confs'){
        void session.release();throw new Error('Локальная модель имеет неподдерживаемый формат');
      }
      return session;
    }).catch(error=>{model=undefined;modelBase=undefined;throw error});
  }
  return model;
}

function frameTensor(frame:ImageBitmap){
  if(!Number.isFinite(frame.width)||!Number.isFinite(frame.height)||frame.width<16||frame.height<16||frame.width>8192||frame.height>8192)throw new Error('Некорректный кадр камеры');
  const canvas=new OffscreenCanvas(SIDE,SIDE);
  const context=canvas.getContext('2d',{willReadFrequently:true});
  if(!context)throw new Error('Обработка кадров не поддерживается');
  context.imageSmoothingEnabled=true;context.imageSmoothingQuality='low';
  context.drawImage(frame,0,0,SIDE,SIDE);
  const rgba=context.getImageData(0,0,SIDE,SIDE).data;
  const pixels=SIDE*SIDE,data=new Float32Array(3*pixels);
  let sum=0,sumSquares=0;
  for(let i=0;i<pixels;i++){
    const offset=i*4,r=rgba[offset],g=rgba[offset+1],b=rgba[offset+2];
    data[i]=r/255;data[pixels+i]=g/255;data[2*pixels+i]=b/255;
    const light=(r+g+b)/3;sum+=light;sumSquares+=light*light;
  }
  const mean=sum/pixels,variance=sumSquares/pixels-mean*mean;
  // This is only a frame-quality gate. Missing/blank imagery never means a print failed.
  if(mean<4||mean>251||variance<4)throw new Error('Кадр слишком тёмный, засвеченный или пустой');
  return new ort.Tensor('float32',data,[1,3,SIDE,SIDE]);
}

const clamp=(value:number)=>Math.max(0,Math.min(1,value));
function overlap(a:CameraFailureBox,b:CameraFailureBox){
  const width=Math.max(0,Math.min(a.x+a.width,b.x+b.width)-Math.max(a.x,b.x));
  const height=Math.max(0,Math.min(a.y+a.height,b.y+b.height)-Math.max(a.y,b.y));
  const intersection=width*height,union=a.width*a.height+b.width*b.height-intersection;
  return union>0?intersection/union:0;
}

function decode(outputs:ort.InferenceSession.ReturnType):CameraDetectionResult{
  const boxes=outputs.boxes,confs=outputs.confs;
  if(!boxes||!confs||boxes.type!=='float32'||confs.type!=='float32'||boxes.dims.join(',')!==`1,${BOX_COUNT},1,4`||confs.dims.join(',')!==`1,${BOX_COUNT},1`)throw new Error('Модель вернула неподдерживаемые координаты');
  const coordinates=boxes.data as Float32Array,scores=confs.data as Float32Array;
  const candidates:CameraFailureBox[]=[];
  for(let index=0;index<BOX_COUNT;index++){
    const score=scores[index],offset=index*4;
    if(!Number.isFinite(score)||score<0||score>1)throw new Error('Модель вернула некорректную оценку');
    if(score<=CANDIDATE_THRESHOLD)continue;
    const values=[coordinates[offset],coordinates[offset+1],coordinates[offset+2],coordinates[offset+3]];
    if(!values.every(Number.isFinite))throw new Error('Модель вернула некорректные координаты');
    const [x,y,right,bottom]=values.map(clamp);
    if(right>x&&bottom>y)candidates.push({x,y,width:right-x,height:bottom-y,score});
  }
  candidates.sort((a,b)=>b.score-a.score);
  const selected:CameraFailureBox[]=[];
  for(const candidate of candidates){
    if(selected.every(other=>overlap(candidate,other)<=NMS_IOU))selected.push(candidate);
    if(selected.length>=MAX_BOXES)break;
  }
  return{score:selected[0]?.score??0,boxes:selected,modelId:CAMERA_DETECTOR_MODEL_ID};
}

scope.onmessage=event=>{
  const {id,frame,assetBase}=event.data;
  if(processing){frame.close();scope.postMessage({id,error:'Модуль анализа занят'});return}
  processing=true;
  void(async()=>{
    let tensor:ort.Tensor|undefined;
    let outputs:ort.InferenceSession.ReturnType|undefined;
    try{
      tensor=frameTensor(frame);
      frame.close();
      const session=await getModel(assetBase);
      outputs=await session.run({input:tensor});
      scope.postMessage({id,result:decode(outputs)});
    }catch(error){scope.postMessage({id,error:error instanceof Error?error.message:'Не удалось проанализировать кадр камеры'})}
    finally{frame.close();tensor?.dispose();if(outputs)for(const value of Object.values(outputs))value.dispose();processing=false}
  })();
};

import type { PrinterModel } from '../types';
import { isCrealityCamera, safeCameraUrl } from '../components/PrinterCamera';

export type CameraGuardSource={kind:'snapshot';url:string;label:string}|{kind:'webrtc';label:string};
export function cameraGuardSource(printer:PrinterModel):CameraGuardSource|undefined{
  for(const camera of printer.webcams){
    if(!camera.enabled)continue;
    const url=safeCameraUrl(printer,camera.snapshot_url);
    if(url)return{kind:'snapshot',url,label:camera.name||'Камера принтера'};
  }
  if(isCrealityCamera(printer))return{kind:'webrtc',label:'Встроенная камера Creality'};
  return undefined;
}

/** Validate actual pixels before inference. Darkness or a repeated picture is
 * an unavailable observation, never evidence that a print has failed. */
export async function prepareCameraFrame(source:CanvasImageSource,width:number,height:number){
  if(!Number.isFinite(width)||!Number.isFinite(height)||width<64||height<64)throw new Error('Камера передала слишком маленький кадр');
  const scale=Math.min(1,1280/width,960/height),canvas=document.createElement('canvas');
  canvas.width=Math.max(1,Math.round(width*scale));canvas.height=Math.max(1,Math.round(height*scale));
  const context=canvas.getContext('2d');if(!context)throw new Error('Не удалось подготовить кадр камеры');
  context.drawImage(source,0,0,canvas.width,canvas.height);
  const probe=document.createElement('canvas');probe.width=64;probe.height=64;
  const pixels=probe.getContext('2d',{willReadFrequently:true});
  if(!pixels)throw new Error('Не удалось прочитать изображение камеры');
  pixels.drawImage(canvas,0,0,64,64);
  const rgba=pixels.getImageData(0,0,64,64).data;
  let sum=0,squares=0;
  for(let i=0;i<rgba.length;i+=4){const value=.2126*rgba[i]+.7152*rgba[i+1]+.0722*rgba[i+2];sum+=value;squares+=value*value;}
  const mean=sum/(64*64),variance=squares/(64*64)-mean*mean;
  if(mean<3||variance<1)throw new Error('Кадр тёмный или пустой — проверь освещение камеры');
  const digest=await crypto.subtle.digest('SHA-256',new Uint8Array(rgba));
  const hash=Array.from(new Uint8Array(digest),n=>n.toString(16).padStart(2,'0')).join('');
  return{bitmap:await createImageBitmap(canvas),hash};
}

import type { PrinterModel } from '../types';

export type CameraGuardMode='off'|'notify'|'pause';
export type CameraGuardSettings={version:1;printers:Record<string,{mode:CameraGuardMode}>};
export type CameraGuardPhase='off'|'waiting'|'warming'|'loading'|'watching'|'suspected'|'warning'|'pausing'|'paused'|'failed'|'unavailable'|'latched';
export type CameraGuardStatus={label:string;tone:'neutral'|'success'|'warning'|'danger';phase:CameraGuardPhase;score?:number;streak?:number;jobToken?:string};
export type CameraFrameContext={capturedAt:number;frameToken:string;sourceEpoch:string;jobToken:string};
type Job={token:string;host:string;filename:string;duration:number;observedAt:number;inactive:boolean};
type Incident={token:string;jobToken:string;minimumPrintDuration:number;mode:Exclude<CameraGuardMode,'off'>;state:'warning'|'queued'|'pending'|'paused'|'failed'|'latched';requestedAt?:number;reported:boolean};
type Entry={job?:Job;generation:number;sourceEpoch?:string;seenTokens:string[];lastCapturedAt?:number;analysedAt?:number;analysing?:boolean;firstSuspicionAt?:number;lastSuspicionAt?:number;streak:number;score?:number;problem?:string;incident?:Incident};
export type CameraGuardTicket={printerId:string;host:string;jobToken:string;filename:string;duration:number;mode:Exclude<CameraGuardMode,'off'>;generation:number;context:CameraFrameContext};
export type CameraGuardTrigger={printerId:string;host:string;jobToken:string;incidentToken:string;filename:string;duration:number;capturedAt:number;score:number;mode:Exclude<CameraGuardMode,'off'>};
export type CameraGuardEvent={printerId:string;jobToken:string;kind:'paused'|'pause_failed';reason?:string};

export const CAMERA_GUARD_KEY='production.cameraGuard.v1';
export const CAMERA_GUARD_LATCH_KEY='production.cameraGuard.incidents.v1';
export type CameraGuardLatches=Record<string,{host:string;filename:string;minimumPrintDuration:number;mode:Exclude<CameraGuardMode,'off'>}>;
export const CAMERA_FRAME_MAX_AGE_MS=15_000;
export const CAMERA_JOB_MAX_AGE_MS=20_000;
export const CAMERA_GUARD_THRESHOLD=.6;
const WARMUP_SECONDS=60,MIN_CONFIRMATION_SPAN_MS=24_000,MAX_STREAK_GAP_MS=20_000,PAUSE_CONFIRMATION_MS=20_000;
export const emptyCameraGuardSettings=():CameraGuardSettings=>({version:1,printers:{}});

export function restoreCameraGuardSettings(value:unknown):CameraGuardSettings{
  if(value===null)return emptyCameraGuardSettings();
  if(!value||typeof value!=='object'||Array.isArray(value))throw new Error('Некорректные настройки защиты камеры');
  const candidate=value as Record<string,unknown>;
  if(candidate.version!==1||!candidate.printers||typeof candidate.printers!=='object'||Array.isArray(candidate.printers))throw new Error('Неизвестный формат настроек защиты камеры');
  const entries=Object.entries(candidate.printers);
  if(entries.length>1000)throw new Error('Слишком много настроек камер');
  const printers:CameraGuardSettings['printers']={};
  for(const [id,raw] of entries){
    if(!id||id.length>256||!raw||typeof raw!=='object'||Array.isArray(raw))throw new Error('Повреждены настройки камеры');
    const mode=(raw as Record<string,unknown>).mode;
    if(mode!=='off'&&mode!=='notify'&&mode!=='pause')throw new Error('Неизвестный режим защиты камеры');
    Object.defineProperty(printers,id,{value:{mode},writable:true,enumerable:true,configurable:true});
  }
  return {version:1,printers};
}

export function restoreCameraGuardLatches(value:unknown):CameraGuardLatches{
  if(value===null)return {};
  if(!value||typeof value!=='object'||Array.isArray(value)||Object.keys(value).length>1000)throw new Error('Некорректная история срабатываний камеры');
  const result:CameraGuardLatches={};
  for(const [id,raw] of Object.entries(value)){
    if(!id||!raw||typeof raw!=='object'||Array.isArray(raw))throw new Error('Повреждена история срабатываний камеры');
    const item=raw as Record<string,unknown>;
    if(typeof item.host!=='string'||!item.host||typeof item.filename!=='string'||!item.filename||typeof item.minimumPrintDuration!=='number'||!Number.isFinite(item.minimumPrintDuration)||item.minimumPrintDuration<0||(item.mode!=='notify'&&item.mode!=='pause'))throw new Error('Повреждена история срабатываний камеры');
    Object.defineProperty(result,id,{value:{host:item.host,filename:item.filename,minimumPrintDuration:item.minimumPrintDuration,mode:item.mode},writable:true,enumerable:true,configurable:true});
  }
  return result;
}

const fresh=(timestamp:unknown,now:number,maximumAge:number)=>typeof timestamp==='number'&&Number.isFinite(timestamp)&&timestamp>0&&now-timestamp>=-2_000&&now-timestamp<=maximumAge;
const activeState=(printer:PrinterModel)=>printer.status.state==='printing'||printer.status.state==='paused';
const hasLiveJob=(printer:PrinterModel,now:number)=>printer.status.connectionState==='online'&&!printer.status.remoteControlSuspended&&activeState(printer)&&!!printer.status.filename?.trim()&&Number.isFinite(printer.status.printDuration)&&printer.status.printDuration>=0&&fresh(printer.status.jobUpdatedAt,now,CAMERA_JOB_MAX_AGE_MS);

/** All decisions use observed job counters and decoded-frame identities, never elapsed wall time as evidence of a failure. */
export class CameraGuardMachine{
  private entries=new Map<string,Entry>();
  private printers=new Map<string,PrinterModel>();
  private sequence=0;
  private events:CameraGuardEvent[]=[];
  private restoredLatches:CameraGuardLatches={};
  settings=emptyCameraGuardSettings();

  restoreLatches(latches:CameraGuardLatches){this.restoredLatches=latches}
  storedLatches():CameraGuardLatches{
    const result={...this.restoredLatches};
    for(const [id,entry] of this.entries)if(entry.job&&entry.incident&&!entry.job.inactive)result[id]={host:entry.job.host,filename:entry.job.filename,minimumPrintDuration:entry.incident.minimumPrintDuration,mode:entry.incident.mode};
    return result;
  }

  mode(id:string):CameraGuardMode{return this.settings.printers[id]?.mode??'off'}
  private entry(id:string){let entry=this.entries.get(id);if(!entry){entry={generation:0,seenTokens:[],streak:0};this.entries.set(id,entry)}return entry}
  private reset(entry:Entry){entry.generation++;entry.streak=0;entry.firstSuspicionAt=undefined;entry.lastSuspicionAt=undefined;entry.score=undefined;entry.analysing=false}
  setSettings(settings:CameraGuardSettings){
    const before=this.settings;this.settings=settings;
    for(const [id,entry] of this.entries)if((before.printers[id]?.mode??'off')!==this.mode(id)){this.reset(entry);entry.problem=undefined}
  }
  observe(printers:PrinterModel[],now:number){
    this.printers=new Map(printers.map(printer=>[printer.id,printer]));
    for(const [id] of this.entries)if(!this.printers.has(id))this.entries.delete(id);
    for(const printer of printers){
      const entry=this.entry(printer.id),live=hasLiveJob(printer,now),duration=printer.status.printDuration;
      if(live){
        const changed=!entry.job||entry.job.host!==printer.host||entry.job.filename!==printer.status.filename||entry.job.inactive||duration+2<entry.job.duration;
        if(changed){
          this.reset(entry);entry.job={token:`${printer.id}:${++this.sequence}`,host:printer.host,filename:printer.status.filename!,duration,observedAt:printer.status.jobUpdatedAt!,inactive:false};
          entry.incident=undefined;entry.problem=undefined;entry.sourceEpoch=undefined;entry.seenTokens=[];entry.lastCapturedAt=undefined;entry.analysedAt=undefined;
          const restored=this.restoredLatches[printer.id];
          if(restored&&restored.host===printer.host&&restored.filename===printer.status.filename&&duration+2>=restored.minimumPrintDuration)entry.incident={token:`restored:${++this.sequence}`,jobToken:entry.job.token,minimumPrintDuration:restored.minimumPrintDuration,mode:restored.mode,state:'latched',reported:true};
          delete this.restoredLatches[printer.id];
        }else if(printer.status.jobUpdatedAt!>=entry.job!.observedAt){
          entry.job={...entry.job!,duration,observedAt:printer.status.jobUpdatedAt!};
        }
      }else if(printer.status.connectionState==='online'&&fresh(printer.status.jobUpdatedAt,now,CAMERA_JOB_MAX_AGE_MS)&&!activeState(printer)&&entry.job){
        entry.job.inactive=true;
      }
      const incident=entry.incident;
      if(incident?.state==='pending'&&incident.jobToken===entry.job?.token){
        if(live&&printer.status.state==='paused'&&printer.status.jobUpdatedAt!>=incident.requestedAt!){
          incident.state='paused';this.events.push({printerId:printer.id,jobToken:incident.jobToken,kind:'paused'});incident.reported=true;
        }else if(now-(incident.requestedAt??now)>=PAUSE_CONFIRMATION_MS||entry.job?.inactive){
          this.fail(printer.id,'Принтер не подтвердил паузу свежим состоянием задания');
        }
      }
      if(!live||printer.status.state!=='printing'||duration<WARMUP_SECONDS){
        if(entry.streak||entry.firstSuspicionAt!==undefined)this.reset(entry);
      }
    }
  }
  drainEvents(){const events=this.events;this.events=[];return events}
  jobToken(id:string,now:number){const printer=this.printers.get(id),entry=this.entries.get(id);return printer&&entry?.job&&hasLiveJob(printer,now)&&!entry.job.inactive?entry.job.token:undefined}
  private eligible(id:string,now:number){const printer=this.printers.get(id),entry=this.entries.get(id);return !!printer&&!!entry?.job&&!entry.job.inactive&&hasLiveJob(printer,now)&&printer.status.state==='printing'&&printer.status.printDuration>=WARMUP_SECONDS}
  beginFrame(id:string,context:CameraFrameContext,now:number):CameraGuardTicket|undefined{
    const entry=this.entries.get(id),printer=this.printers.get(id),mode=this.mode(id);
    if(!entry?.job||!printer||mode==='off'||!this.eligible(id,now)||entry.incident||context.jobToken!==entry.job.token)return undefined;
    if(!context.frameToken||!context.sourceEpoch||!fresh(context.capturedAt,now,CAMERA_FRAME_MAX_AGE_MS)){this.reset(entry);return undefined}
    if(entry.sourceEpoch!==context.sourceEpoch){this.reset(entry);entry.sourceEpoch=context.sourceEpoch;entry.seenTokens=[];entry.lastCapturedAt=undefined;entry.analysedAt=undefined}
    if(entry.seenTokens.includes(context.frameToken)||(entry.lastCapturedAt!==undefined&&context.capturedAt<=entry.lastCapturedAt))return undefined;
    entry.seenTokens=[...entry.seenTokens.slice(-15),context.frameToken];entry.lastCapturedAt=context.capturedAt;entry.problem=undefined;entry.analysing=true;
    return {printerId:id,host:printer.host,jobToken:entry.job.token,filename:entry.job.filename,duration:entry.job.duration,mode,generation:entry.generation,context};
  }
  completeFrame(ticket:CameraGuardTicket,score:number,now:number):CameraGuardTrigger|undefined{
    const entry=this.entries.get(ticket.printerId);
    if(entry?.generation===ticket.generation)entry.analysing=false;
    if(!entry||entry.generation!==ticket.generation||entry.job?.token!==ticket.jobToken||entry.job.host!==ticket.host||this.mode(ticket.printerId)!==ticket.mode||entry.incident||!this.eligible(ticket.printerId,now)||!fresh(ticket.context.capturedAt,now,CAMERA_FRAME_MAX_AGE_MS))return undefined;
    if(!Number.isFinite(score)||score<0||score>1){this.unavailable(ticket.printerId,'Модель вернула недопустимый результат');return undefined}
    entry.score=score;entry.analysedAt=now;
