    if(entry?.incident){
      const incident=entry.incident;
      if(incident.state==='queued'||incident.state==='pending')return {...base,phase:'pausing',label:incident.state==='queued'?'Готовим команду паузы':'Ожидаем подтверждение паузы',tone:'warning'};
      if(incident.state==='failed')return {...base,phase:'failed',label:entry.problem||'Пауза не подтверждена. Проверьте принтер',tone:'danger'};
      if(incident.state==='latched')return {...base,phase:'latched',label:entry.problem||'Защита уже срабатывала. Повторная автопауза до нового задания отключена',tone:'warning'};
      if(incident.state==='paused'&&printer?.status.state==='paused')return {...base,phase:'paused',label:'Печать приостановлена защитой камеры',tone:'danger'};
      if(incident.state==='paused')return {...base,phase:'latched',label:'Автопауза уже сработала для этого задания',tone:'warning'};
      return {...base,phase:'warning',label:'Камера обнаружила признаки сбоя. Проверьте печать',tone:'danger'};
    }
    if(!printer||!hasLiveJob(printer,now))return {...base,phase:'waiting',label:printer?.status.connectionState==='online'?'Ожидаем печать':'Нет свежего состояния принтера',tone:'neutral'};
    if(printer.status.state==='paused')return {...base,phase:'waiting',label:'Проверка приостановлена вместе с печатью',tone:'neutral'};
    if(printer.status.printDuration<WARMUP_SECONDS)return {...base,phase:'warming',label:'Первые 60 секунд: ожидаем начало печати',tone:'neutral'};
    if(entry?.problem)return {...base,phase:'unavailable',label:entry.problem,tone:'warning'};
    if(mode==='pause'&&printer.capabilities?.canPause===false)return {...base,phase:'unavailable',label:'Принтер не поддерживает команду паузы',tone:'warning'};
    if(entry?.analysedAt&&now-entry.analysedAt>25_000)return {...base,phase:'unavailable',label:'Нет свежих кадров для проверки печати',tone:'warning'};
    if(entry?.streak)return {...base,phase:'suspected',label:`Проверяем подозрение · ${Math.min(entry.streak,4)}/4 кадра`,tone:'warning'};
    if(entry?.analysing&&!entry.analysedAt)return {...base,phase:'loading',label:'Загружаем модель и проверяем первый кадр',tone:'neutral'};
    return {...base,phase:'watching',label:entry?.analysedAt?'Камера наблюдает за печатью':'Ожидаем свежий кадр камеры',tone:entry?.analysedAt?'success':'neutral'};
  }
  statuses(now:number){return Object.fromEntries([...this.printers.keys()].map(id=>[id,this.status(id,now)]))}
  activePrinterIds(now:number){return [...this.printers.keys()].filter(id=>this.mode(id)!=='off'&&this.eligible(id,now)&&!this.entries.get(id)?.incident)}
}

