        const [raw,rawLatches]=await Promise.all([secureInvoke<string|null>('db_get_json',{key:CAMERA_GUARD_KEY}),secureInvoke<string|null>('db_get_json',{key:CAMERA_GUARD_LATCH_KEY})]);
