export type TvState='printing'|'ready'|'paused'|'error'|'offline'|'unknown';
export const TV_STATES:readonly TvState[]=['printing','ready','paused','error','offline','unknown'];
export const TV_STATE_LABELS:Record<TvState,string>={printing:'Печатает',ready:'Готов',paused:'Пауза',error:'Ошибка',offline:'Нет связи',unknown:'Нет данных'};
export type TvNotice={id:string;printerId:string;printerName:string;label:string;detail:string;tone:'warning'|'danger';priority:number};
const finite=(value:unknown):value is number=>typeof value==='number'&&Number.isFinite(value);

/** Presentation only: a missing or old job snapshot never becomes “ready”. */
export function tvPrinterState(printer:PrinterModel,now:number):TvState{
  const s=printer.status;
  if(s.remoteControlSuspended)return'unknown';
  if(s.connectionState==='offline'||s.state==='offline')return'offline';
  if(s.state==='error'||s.klippyState==='error'||s.klippyState==='shutdown'||s.connectionReason==='authorization'||s.connectionReason==='quarantine')return'error';
  if(s.connectionState==='connecting')return'unknown';
  const freshness=jobFreshness(s,now);
  if(freshness==='expired'||freshness==='unavailable')return'unknown';
  if(s.state==='printing')return'printing';
  if(s.state==='paused')return'paused';
  return s.state==='ready'&&s.connectionState==='online'?'ready':'unknown';
}

export function tvProgress(printer:PrinterModel,now:number){
  const freshness=jobFreshness(printer.status,now);
  return freshness==='expired'||freshness==='unavailable'||!finite(printer.status.progress)?undefined:Math.round(Math.max(0,Math.min(1,printer.status.progress))*100);
}

/** Estimate from printer elapsed duration and progress; never an invented UI countdown. */
export function tvRemainingSeconds(printer:PrinterModel,now:number):number|undefined{
  const s=printer.status;
  if(tvPrinterState(printer,now)!=='printing'||jobFreshness(s,now)!=='live'||!finite(s.progress)||s.progress<=.01||s.progress>=1||!finite(s.printDuration)||s.printDuration<60)return;
  return Math.max(0,s.printDuration*(1-s.progress)/s.progress);
}

export function tvDuration(seconds:number){
  const minutes=Math.max(1,Math.ceil(seconds/60)),hours=Math.floor(minutes/60),rest=minutes%60;
  return hours?`${hours} ч${rest?` ${rest} мин`:''}`:`${minutes} мин`;
}

export function tvFreshness(printer:PrinterModel,now:number){
  const s=printer.status,job=jobFreshness(s,now),telemetry=telemetryFreshness(s,now);
  if(s.connectionState==='offline'||s.state==='offline')return {tone:'offline',label:s.lastSeen?`Последний ответ ${compactAge(s.lastSeen,now)}`:'Принтер не отвечает'};
  if(s.remoteControlSuspended)return {tone:'stale',label:'Удалённые данные не подтверждаются'};
  if(job==='live'&&telemetry==='live')return {tone:'live',label:'Данные актуальны'};
  const oldest=Math.min(s.jobUpdatedAt??0,s.telemetryUpdatedAt??0);
  if(!oldest)return {tone:'unknown',label:'Ожидаем данные принтера'};
  return {tone:job==='expired'||telemetry==='expired'?'unknown':'stale',label:`${job==='expired'||telemetry==='expired'?'Нет свежих данных':'Данные устарели'} · ${compactAge(oldest,now)}`};
}

export function tvSummary(printers:PrinterModel[],now:number){
  const counts:Record<TvState,number>={printing:0,ready:0,paused:0,error:0,offline:0,unknown:0};
  printers.forEach(printer=>counts[tvPrinterState(printer,now)]++);
  return counts;
}

export function tvDueTasks(printerId:string,maintenance?:MaintenanceState){
  return maintenance?.tasks.filter(task=>task.printerId===printerId&&maintenanceProgress(task,maintenance.meters).due)??[];
}

export function tvNotices(printers:PrinterModel[],now:number,maintenance?:MaintenanceState):TvNotice[]{
  const notices:TvNotice[]=[];
  for(const printer of printers){
    const state=tvPrinterState(printer,now),freshness=tvFreshness(printer,now),s=printer.status;
    if(state==='error'||state==='offline'||state==='paused'||state==='unknown'){
      const label=state==='unknown'&&s.remoteControlSuspended?'Автономная печать':TV_STATE_LABELS[state];
      const detail=state==='paused'?'Печать приостановлена':state==='unknown'?freshness.label:state==='error'?s.message||s.connectionMessage||'Принтер сообщил об ошибке':s.connectionMessage||freshness.label;
      notices.push({id:`status:${printer.id}`,printerId:printer.id,printerName:printer.name,label,detail,tone:state==='error'?'danger':'warning',priority:state==='error'?0:state==='offline'?1:state==='paused'?2:4});
    }else if(freshness.tone!=='live'||s.connectionState==='degraded')notices.push({id:`freshness:${printer.id}`,printerId:printer.id,printerName:printer.name,label:'Проверить связь',detail:s.connectionState==='degraded'?s.connectionMessage||'Связь с принтером нестабильна':freshness.label,tone:'warning',priority:3});
    const due=tvDueTasks(printer.id,maintenance);
    if(due.length)notices.push({id:`maintenance:${printer.id}`,printerId:printer.id,printerName:printer.name,label:'Пора обслужить',detail:due.map(task=>task.title).join(' · '),tone:'warning',priority:3});
  }
  return notices.sort((a,b)=>a.priority-b.priority);
}

/** Paging keeps cards legible and avoids opening off-screen camera streams. */
export function tvLayout(width:number,height:number){
  if(width<600)return {columns:1,pageSize:height<650?1:2};
  if(width<1100)return {columns:2,pageSize:height<650?2:4};
  if(height<650)return {columns:3,pageSize:3};
  if(width<1600||height<900)return {columns:3,pageSize:6};
  return {columns:4,pageSize:8};
}

import {analyzeCameraFrame,disposeCameraDetector} from '../src/lib/cameraDetector';
import type {CameraDetectionResult} from '../src/lib/cameraDetector';

const loadImage=async(path:string)=>{
  const image=new Image();image.src=path;await image.decode();return image;
};
const failureFrame=async()=>createImageBitmap(await loadImage('/__camera-fixtures/failure.png'));
const normalFrame=async()=>createImageBitmap(await loadImage('/__camera-fixtures/normal.jpg'),531,214,936,704);
const blankFrame=async()=>createImageBitmap(new ImageData(new Uint8ClampedArray(416*416*4),416,416));
const result=(value:CameraDetectionResult)=>({score:value.score,modelId:value.modelId,boxes:value.boxes});
(window as any).__cameraDetector={
  failure:async()=>result(await analyzeCameraFrame(await failureFrame())),
  normal:async()=>result(await analyzeCameraFrame(await normalFrame())),
  blank:async()=>{
    try{await analyzeCameraFrame(await blankFrame());return{rejected:false}}
    catch(error){return{rejected:true,error:String(error)}}
  },
  abort:async()=>{
    const controller=new AbortController(),frame=await failureFrame();
    const pending=analyzeCameraFrame(frame,controller.signal);controller.abort();
    try{await pending;return{rejected:false}}
    catch(error){return{rejected:true,error:String(error)}}
  },
  dispose:disposeCameraDetector,
};
document.querySelector('#status')!.textContent='Ready';

import assert from 'node:assert/strict';
import fs from 'node:fs';
import path from 'node:path';
import os from 'node:os';
import http from 'node:http';
import crypto from 'node:crypto';
import {build} from 'vite';
import {prepareCameraDetector} from '../scripts/prepare-camera-detector.mjs';

const root=path.resolve(import.meta.dirname,'..');
const guardChain=process.argv.includes('--guard-chain');
const temporary=fs.mkdtempSync(path.join(os.tmpdir(),'kf-camera-detector-'));
const out=path.join(temporary,'site');
const reportDirectory=process.env.KF_UI_SCREENSHOTS??path.join(root,'camera-detector-results');
const productionCsp=JSON.parse(fs.readFileSync(path.join(root,'src-tauri','tauri.conf.json'),'utf8')).app.security.csp;
const revision='6f938964c63892df2b6d5b68d99ea783fc1a7c78';
const fixtures={
  'failure.png':{path:'website/static/img/user-guides/spaghetti-examples/11.png',size:218802,sha256:'421c365a31a5c6791527662a7fc9bc20a6545db874b7bb077e2a47772997192c'},
  'normal.jpg':{path:'website/static/img/user-guides/helpdocs/shared-printer-feed.jpg',size:238495,sha256:'d48baf81b7663b74a3526bc1de16d9b944c70b5a0844353ac2bf1045530120e4'},
};
let server,browser;
const report={model:undefined,fixtures:{revision,source:'https://github.com/TheSpaghettiDetective/obico-server',sourceLicense:'AGPL-3.0',files:fixtures},productionCsp,results:[],requests:[],pageErrors:[],status:'running'};
try{
  report.model=await prepareCameraDetector();
  await build({root,logLevel:'warn',worker:{format:'es'},build:{outDir:out,emptyOutDir:true,rollupOptions:{input:path.join(root,guardChain?'ui-tests/camera-guard-chain.html':'ui-tests/camera-detector.html')}}});
  if(process.argv.includes('--build-only'))console.log('Local camera detector worker fixture build OK');
  else{
    const bytes=new Map();
    for(const[name,fixture]of Object.entries(fixtures)){
      const url=`https://raw.githubusercontent.com/TheSpaghettiDetective/obico-server/${revision}/${fixture.path}`;
      const response=await fetch(url,{signal:AbortSignal.timeout(30_000)});
      assert.ok(response.ok,`Fixture download failed: ${name} HTTP ${response.status}`);
      const data=Buffer.from(await response.arrayBuffer());
      assert.equal(data.length,fixture.size,`${name} size`);
      assert.equal(crypto.createHash('sha256').update(data).digest('hex'),fixture.sha256,`${name} SHA256`);
      bytes.set(name,data);
    }
    server=http.createServer((request,response)=>{
      response.setHeader('Content-Security-Policy',productionCsp);
      const pathname=new URL(request.url,'http://localhost').pathname;
      if(pathname.startsWith('/__camera-fixtures/')){
        const name=pathname.slice('/__camera-fixtures/'.length),data=bytes.get(name);
        if(!data){response.writeHead(404);response.end();return}
        response.setHeader('Content-Type',name.endsWith('.png')?'image/png':'image/jpeg');response.end(data);return;
      }
      const file=path.resolve(out,pathname.slice(1));
      if(!file.startsWith(out+path.sep)||!fs.existsSync(file)||!fs.statSync(file).isFile()){response.writeHead(404);response.end();return}
      response.setHeader('Content-Type',({'.js':'text/javascript','.mjs':'text/javascript','.wasm':'application/wasm','.html':'text/html','.json':'application/json'})[path.extname(file)]??'application/octet-stream');
      fs.createReadStream(file).pipe(response);
    });
    await new Promise(resolve=>server.listen(0,'127.0.0.1',resolve));
    const origin=`http://127.0.0.1:${server.address().port}`;
    const {chromium}=await import(process.env.PLAYWRIGHT_MODULE_PATH??'playwright');
    browser=await chromium.launch({headless:true,...(process.platform==='win32'?{channel:'msedge'}:{})});
    const context=await browser.newContext();
    await context.route('**/*',route=>{
      const url=route.request().url();
      report.requests.push(url);
      if(new URL(url).origin!==origin)return route.abort();
      return route.continue();
    });
    const page=await context.newPage();page.setDefaultTimeout(150_000);
    page.on('pageerror',error=>report.pageErrors.push(String(error)));
    await page.goto(origin+(guardChain?'/ui-tests/camera-guard-chain.html':'/ui-tests/camera-detector.html'));
    if(guardChain){
      await page.waitForFunction(()=>window.__cameraGuardChain?.ready&&window.__cameraGuardChain?.mode==='pause');
      assert.equal(await page.locator('.tvPanel,.tvWall,[role="dialog"]').count(),0,'Camera host must run with no TV window');
      await page.waitForFunction(()=>window.__cameraGuardChain?.records.pauses.length===1&&window.__cameraGuardChain?.status?.phase==='paused',{},{timeout:90_000});
      await page.waitForFunction(()=>window.__cameraGuardChain?.records.audit.some(item=>item.action==='camera.paused'));
      await page.waitForTimeout(2_000);
      const state=await page.evaluate(()=>{const value=window.__cameraGuardChain;return{records:value.records,status:value.status,printerState:value.printerState,mode:value.mode}});
      assert.equal(state.records.pauses.length,1,'Exactly one guarded pause for the same print');
      assert.equal(state.printerState,'paused');assert.equal(state.status.phase,'paused');
      assert.ok(state.records.snapshots.length>=4,'At least four real Host captures are required');
      assert.ok(state.records.snapshots[3].at-state.records.snapshots[0].at>=24_000,'Production Host sampling interval must be preserved');
      assert.ok(state.records.pauses[0].latchSavedAt<=state.records.pauses[0].at,'Incident must be durably written before command');
      assert.ok(state.records.audit.some(item=>item.action==='camera.warning'),'Suspicion notification');
      assert.ok(state.records.audit.some(item=>item.action==='camera.paused'),'Confirmed pause notification');
      assert.ok(state.records.notifications.some(item=>item.title.includes('печать приостановлена')),'Visible pause notification');
      assert.ok(state.records.native.length>0,'Native notification boundary must be called');
      report.results.push({test:'actual-capture-model-guard-pause-chain-without-tv',status:'passed',...state});
      assert.deepEqual(report.pageErrors,[],'No integration page exceptions');
      assert.ok(report.requests.some(url=>url.endsWith('.onnx')),'Real model must be loaded');
      assert.ok(report.requests.some(url=>url.endsWith('.wasm')),'Real inference runtime must be loaded');
      assert.ok(report.requests.every(url=>new URL(url).origin===origin),'Camera inference must stay local');
      report.status='passed';console.log('Camera guard chain acceptance passed: actual Host frames, real local ONNX, durable incident, one protected pause and confirmed notification, without TV');
    }else{
    await page.waitForFunction(()=>!!window.__cameraDetector);
    const positive=await page.evaluate(()=>window.__cameraDetector.failure());
    assert.equal(positive.modelId,'obico-failure-5a6b1be1fa');
    assert.ok(positive.score>.60&&positive.score<=1,'Real visible spaghetti must produce a strong failure score');
    assert.ok(positive.boxes.length>0&&positive.boxes.every(box=>Number.isFinite(box.score)&&box.x>=0&&box.y>=0&&box.x+box.width<=1.00001&&box.y+box.height<=1.00001),'Normalized failure boxes');
    report.results.push({test:'real-spaghetti-frame',status:'passed',...positive});
    const normal=await page.evaluate(()=>window.__cameraDetector.normal());
    assert.ok(normal.score<.1,'Healthy print camera crop must not trigger');
    report.results.push({test:'real-healthy-print-camera-crop',status:'passed',...normal});
    const blank=await page.evaluate(()=>window.__cameraDetector.blank());
    assert.ok(blank.rejected,'Blank camera frame must produce an analysis error, not a failure score');
    report.results.push({test:'blank-frame-is-indeterminate',status:'passed',...blank});
    const cancelled=await page.evaluate(()=>window.__cameraDetector.abort());
    assert.ok(cancelled.rejected,'Cancelled inference must reject');
    report.results.push({test:'cancel-in-flight-inference',status:'passed',...cancelled});
    const recovered=await page.evaluate(()=>window.__cameraDetector.failure());
    assert.ok(recovered.score>.60,'Worker must continue after one camera cancels');
    report.results.push({test:'worker-continues-after-camera-cancel',status:'passed',...recovered});
    await page.evaluate(()=>window.__cameraDetector.dispose());
    const reinitialized=await page.evaluate(()=>window.__cameraDetector.failure());
    assert.ok(reinitialized.score>.60,'Worker must reinitialize after disposal');
    report.results.push({test:'worker-reinitialize-after-dispose',status:'passed',...reinitialized});
    await page.evaluate(()=>window.__cameraDetector.dispose());
    assert.deepEqual(report.pageErrors,[],'No worker/page exceptions');
    assert.ok(report.requests.some(url=>url.endsWith('.onnx')),'Real model must be loaded');
    assert.ok(report.requests.some(url=>url.endsWith('.wasm')),'WASM runtime must be loaded');
    assert.ok(report.requests.every(url=>new URL(url).origin===origin),'Inference must be fully local');
    report.status='passed';console.log('Local camera detector acceptance passed: real positive/healthy frames, quality gate, abort and worker recovery under CSP');
    }
  }
}catch(error){report.status='failed';report.error=String(error?.stack??error);throw error}
finally{
  fs.mkdirSync(reportDirectory,{recursive:true});fs.writeFileSync(path.join(reportDirectory,guardChain?'camera-guard-chain-results.json':'camera-detector-results.json'),JSON.stringify(report,null,2)+'\n');
  await browser?.close();await new Promise(resolve=>server?server.close(resolve):resolve());fs.rmSync(temporary,{recursive:true,force:true});
}

import {useEffect,useRef,useState} from 'react';
