// Only the printer transport and native persistence/notification boundary are
// emulated. CameraGuardHost, frame preparation, ONNX worker and guard hook are real.
const w=window as any;
const memory=new Map<string,string>();
const startedAt=Date.now();
const records={startedAt,snapshots:[] as {index:number;at:number}[],writes:[] as {key:string;at:number;value:unknown}[],pauses:[] as {at:number;latchSavedAt:number;expected:unknown}[],audit:[] as {action:string;details:string;at:number}[],notifications:[] as unknown[],native:[] as unknown[]};
memory.set(CAMERA_GUARD_KEY,JSON.stringify({version:1,printers:{}}));
memory.set(CAMERA_GUARD_LATCH_KEY,'{}');
w.__TAURI_INTERNALS__={invoke:async(command:string,args:any={})=>{
  if(command==='db_get_json')return memory.get(args.key)??null;
  if(command==='db_set_json'){memory.set(args.key,args.value);records.writes.push({key:args.key,at:Date.now(),value:JSON.parse(args.value)});return null}
  if(command==='audit_add'){records.audit.push({action:args.action,details:args.details,at:Date.now()});return null}
  if(command==='native_notify'){records.native.push(args);return null}
  throw new Error('Unexpected integration fixture native command '+command);
}};
setAuthSession({token:'camera-chain-test-only',user:{id:'fixture-operator',name:'Fixture operator',role:'operator',enabled:true,createdAt:0}});
window.addEventListener('klipper-app-notification',event=>records.notifications.push((event as CustomEvent).detail));

let updatePrinter:(update:(printer:PrinterModel)=>PrinterModel)=>void=()=>{throw new Error('Fixture printer is not mounted')};
const positiveImage=new Image();positiveImage.src='/__camera-fixtures/failure.png';
let snapshotIndex=0;
const client={
  snapshot:async()=>{
    await positiveImage.decode();
    const canvas=document.createElement('canvas');canvas.width=positiveImage.width;canvas.height=positiveImage.height;
    const context=canvas.getContext('2d')!;context.drawImage(positiveImage,0,0);
    const index=++snapshotIndex;
    // A visible sequence mark emulates a freshly decoded camera frame. The
    // underlying public spaghetti example remains visible to the real model.
    context.fillStyle=`hsl(${index*37},90%,50%)`;context.fillRect(canvas.width-38,canvas.height-30,38,30);
    context.fillStyle='black';context.font='16px sans-serif';context.fillText(String(index),canvas.width-33,canvas.height-9);
    const blob=await new Promise<Blob>((resolve,reject)=>canvas.toBlob(value=>value?resolve(value):reject(new Error('Fixture PNG encoding failed')),'image/png'));
    records.snapshots.push({index,at:Date.now()});
    return{status:200,contentType:'image/png',body:Array.from(new Uint8Array(await blob.arrayBuffer()))};
  },
  guardedPause:async(expected:{filename:string;minimumPrintDuration:number},applicable:()=>boolean)=>{
    const latched=JSON.parse(memory.get(CAMERA_GUARD_LATCH_KEY)||'{}')['fixture-printer'];
    const saved=records.writes.filter(write=>write.key===CAMERA_GUARD_LATCH_KEY).at(-1);
    if(!latched||!saved||latched.mode!=='pause'||latched.filename!==expected.filename)throw new Error('Incident was not persisted before pause');
    if(expected.filename!=='fixture-spaghetti.gcode'||expected.minimumPrintDuration<60)throw new Error('Pause targeted the wrong print');
    if(!applicable())throw new Error('Guard refused stale pause');
    records.pauses.push({at:Date.now(),latchSavedAt:saved.at,expected});
    updatePrinter(printer=>({...printer,status:{...printer.status,state:'paused',jobUpdatedAt:Date.now(),telemetryUpdatedAt:Date.now()}}));
  },
} as unknown as MoonrakerClient;
const clients=new Map([['fixture-printer',client]]);
const initialPrinter={
  id:'fixture-printer',name:'Camera chain fixture printer',host:'192.168.1.220:7125',icon:'ender',
  webcams:[{name:'Fixture camera',enabled:true,stream_url:'/webcam/?action=stream',snapshot_url:'/webcam/?action=snapshot'}],
  status:{state:'printing',connectionState:'online',filename:'fixture-spaghetti.gcode',printDuration:120,progress:.4,nozzle:205,nozzleTarget:210,bed:60,bedTarget:60,jobUpdatedAt:Date.now(),telemetryUpdatedAt:Date.now()},
} as PrinterModel;

function Fixture(){
  const [printer,setPrinter]=useState(initialPrinter);
  updatePrinter=setPrinter;
  const controller=useCameraGuard({printers:[printer],clients,enabled:true});
  const armed=useRef(false);
  useEffect(()=>{if(controller.ready&&!armed.current){armed.current=true;controller.setMode(printer.id,'pause')}},[controller.ready]);
  useEffect(()=>{
    const timer=window.setInterval(()=>setPrinter(current=>({...current,status:{...current.status,printDuration:current.status.printDuration+(current.status.state==='printing'?1:0),jobUpdatedAt:Date.now(),telemetryUpdatedAt:Date.now()}})),1_000);
    return()=>window.clearInterval(timer);
  },[]);
  w.__cameraGuardChain={records,memory,ready:controller.ready,status:controller.statuses[printer.id],printerState:printer.status.state,mode:controller.settings.printers[printer.id]?.mode};
  return <><p id="status">Camera chain fixture · {controller.statuses[printer.id]?.label??'loading'}</p><CameraGuardHost printers={[printer]} clients={clients} controller={controller}/></>;
}
