        const mode=page.getByRole('combobox',{name:'Контроль камеры: '+expectedNames[0],exact:true});await mode.selectOption('pause');await page.getByRole('alert').waitFor();assert.match(await page.getByRole('alert').innerText(),/не сохранён.*не включена/);assert.equal(await mode.inputValue(),'off');assert.deepEqual(await page.evaluate(()=>window.__guard.activePrinterIds),[]);assert.equal(await page.evaluate(()=>window.__memory.has('production.cameraGuard.v1')),false);
        await page.evaluate(()=>{window.__failWrites=false});await page.getByRole('button',{name:'Повторить',exact:true}).click();await page.waitForFunction(()=>window.__guard.settings.printers['printer-0']?.mode==='pause'&&!window.__guard.error);assert.equal(await mode.inputValue(),'pause');report.push({test:'arming-requires-durable-settings-write',status:'passed'});console.log('PASS camera arming requires durable settings write');await page.close();
